window.FM_DATA = window.FM_DATA || {};
window.FM_DATA["data"] = {"id":"data","title":"Data & Localization","entries":[{"id":"csv-utility","name":"CsvUtility","cat":"Data","src_typeKind":"class","src_ns":"Toolkit.Data","src_file":"Data/Csv/CsvUtility.cs","src_lines":[11,87],"src_base":null,"src_implements":[],"src_static":true,"src_internal":false,"src_runtime":true,"src_attributes":{},"src_typeComment":"Minimal, dependency-free CSV reader/writer — handles quoted fields (commas/newlines inside quotes, escaped \"\" for a literal quote), which a naive string.Split(',') gets wrong. Both Excel and Google Sheets read/write this exact format natively, so this is the practical way to move data between a spreadsheet and Unity without needing a binary .xlsx parsing library.","src_serialized":[],"src_members":[{"id":"Parse(string)","sig":"public static List<string[]> Parse(string csvText)","kind":"method","name":"Parse","static":true,"comment":null},{"id":"ToCsv(IReadOnlyList<string[]>)","sig":"public static string ToCsv(IReadOnlyList<string[]> rows)","kind":"method","name":"ToCsv","static":true,"comment":null},{"id":"EscapeField(string)","sig":"public static string EscapeField(string field)","kind":"method","name":"EscapeField","static":true,"comment":"Public because a caller that lays fields out itself - the localisation exporter pads its columns so the file reads as a table in a plain text editor - has to know how wide each field will be AFTER escaping. Re-implementing the quoting rules there would be a second copy to keep in sync."},{"id":"ReadFile(string)","sig":"public static List<string[]> ReadFile(string path) => Parse(File.ReadAllText(path))","kind":"method","name":"ReadFile","static":true,"comment":null},{"id":"WriteFile(string, IReadOnlyList<string[]>)","sig":"public static void WriteFile(string path, IReadOnlyList<string[]> rows) => File.WriteAllText(path, ToCsv(rows))","kind":"method","name":"WriteFile","static":true,"comment":null}],"src_enumValues":[],"src_selfTest":null,"src_demoScene":["Persistence_Demo"],"entryKind":"tool","status":"published","summary":"Dependency-free CSV parse and write that handles quoted fields correctly.","overview":["Reads and writes the CSV dialect Excel and Google Sheets use natively, so a spreadsheet is a practical data pipeline into Unity with no .xlsx library involved. It handles the part a naive string.Split(',') gets wrong: commas and newlines inside quoted fields, and a doubled \"\" meaning a literal quote."],"useCases":["Authoring item, enemy or dialogue tables in a spreadsheet and reading them at runtime or import time.","Exporting captured play data for analysis in a spreadsheet.","Round-tripping data through the CSV Table Editor window without a binary format."],"gotchas":[{"title":"Rows are string arrays, not typed objects","body":"Parse returns List<string[]> with no header handling and no type conversion. Deciding row 0 is a header, and turning \"12\" into an int, is the caller's job."},{"title":"Ragged rows are preserved, not padded","body":"A row with fewer fields than the header comes back shorter. Index defensively, or normalise after parsing."}],"seeAlso":["CsvTableWindow","CsvToScriptableObjectImporter"],"src_uses":[],"src_usedBy":["CsvTableWindow","CsvToScriptableObjectImporter","LocalizationCsv","LocalizationJson","LocalizationTable"],"src_extensionPoints":[]},{"id":"localization","name":"Localization","cat":"Data","src_typeKind":"class","src_ns":"Toolkit.Data.Localization","src_file":"Data/Localization/LocalizationManager.cs","src_lines":[29,362],"src_base":"Singleton<LocalizationManager>","src_implements":[],"src_static":false,"src_internal":false,"src_runtime":true,"src_attributes":{"addComponentMenu":"Toolkit/Localization/Localization Manager"},"src_typeComment":"Drop this in the first scene, assign a LocaleRegistry, done: every LocalizedText in the project reads from it and updates the moment the language changes.  Lookup order for one key: the CURRENT locale, then the FALLBACK locale, then the missing-key display. The fallback step is what makes a half-translated language usable — the lines the translator has finished appear in their language, the rest stay readable in the fallback rather than going blank.","src_serialized":[{"name":"registry","type":"LocaleRegistry","default":null,"tooltip":"Every language the game ships with. Create one via Assets > Create > Toolkit > Localization > Locale Registry, or let the Localization Importer build it for you.","header":null,"range":null,"order":0,"comment":null},{"name":"defaultLocaleCode","type":"string","default":"\"en\"","tooltip":"Locale code used when there is no saved choice and no system-language match.","header":null,"range":null,"order":1,"comment":null},{"name":"fallbackLocaleCode","type":"string","default":"\"en\"","tooltip":"Locale code consulted when a key is missing from the current locale. Normally the language the game was written in. Leave empty to disable fallback.","header":null,"range":null,"order":2,"comment":null},{"name":"matchSystemLanguageOnFirstRun","type":"bool","default":"true","tooltip":"On a first launch (no saved choice), pick the locale whose Target System Language matches the device. Only locales that actually declare one can be matched.","header":null,"range":null,"order":3,"comment":null},{"name":"rememberSelection","type":"bool","default":"true","tooltip":"Persist the chosen language in PlayerPrefs so it survives a restart. A single string does not justify its own save file, which is why this does not go through SaveSystem.","header":null,"range":null,"order":4,"comment":null},{"name":"playerPrefsKey","type":"string","default":"\"Toolkit.Localization.Locale\"","tooltip":"PlayerPrefs key used when Remember Selection is on.","header":null,"range":null,"order":5,"comment":null},{"name":"missingKeyDisplay","type":"MissingKeyDisplay","default":"MissingKeyDisplay.MarkedKey","tooltip":"What to show for a key that exists in neither the current nor the fallback locale.","header":null,"range":null,"order":6,"comment":null},{"name":"logMissingKeys","type":"bool","default":"true","tooltip":"Log a warning the FIRST time each missing key is asked for. Once per key, not once per frame — a LocalizedText on every label would otherwise flood the console.","header":null,"range":null,"order":7,"comment":null}],"src_members":[{"id":"LocaleChangedEvent()","sig":"public LocaleChangedEvent OnLocaleChanged = new LocaleChangedEvent()","kind":"method","name":"LocaleChangedEvent","static":false,"comment":null},{"id":"CurrentLocaleCode","sig":"public string CurrentLocaleCode","kind":"property","name":"CurrentLocaleCode","static":false,"comment":"These call EnsureInitialized like every other public entry point does. They are the ones most likely to be touched FIRST — a language picker reads AvailableLocaleCodes before anything asks for a string — and an expression-bodied property that skipped the lazy-init would report an empty toolkit for no visible reason."},{"id":"CurrentLocaleDisplayName","sig":"public string CurrentLocaleDisplayName","kind":"property","name":"CurrentLocaleDisplayName","static":false,"comment":null},{"id":"CurrentFont","sig":"public TMP_FontAsset CurrentFont","kind":"property","name":"CurrentFont","static":false,"comment":null},{"id":"AvailableLocaleCodes","sig":"public IReadOnlyList<string> AvailableLocaleCodes","kind":"property","name":"AvailableLocaleCodes","static":false,"comment":null},{"id":"Get(string)","sig":"public string Get(string key)","kind":"method","name":"Get","static":false,"comment":null},{"id":"Get(string, params object[])","sig":"public string Get(string key, params object[] args)","kind":"method","name":"Get","static":false,"comment":"string.Format is wrapped because a translator turning \"You have {0} coins\" into \"You have {0 coins\" throws FormatException at runtime, in a language nobody on the team reads. Falling back to the unformatted template keeps the game running and names the offending key in the console."},{"id":"IsTranslated(string)","sig":"public bool IsTranslated(string key)","kind":"method","name":"IsTranslated","static":false,"comment":"True only if the CURRENT locale has the key — i.e. it is genuinely translated, not merely resolvable through the fallback. That distinction is what a translation-progress readout needs."},{"id":"HasKey(string)","sig":"public bool HasKey(string key)","kind":"method","name":"HasKey","static":false,"comment":null},{"id":"TranslatedKeyCount","sig":"public int TranslatedKeyCount","kind":"property","name":"TranslatedKeyCount","static":false,"comment":null},{"id":"GetDisplayName(string)","sig":"public string GetDisplayName(string localeCode)","kind":"method","name":"GetDisplayName","static":false,"comment":null},{"id":"GetFont(string)","sig":"public TMP_FontAsset GetFont(string localeCode)","kind":"method","name":"GetFont","static":false,"comment":null},{"id":"SetLocale(string)","sig":"public bool SetLocale(string localeCode)","kind":"method","name":"SetLocale","static":false,"comment":null},{"id":"SetRegistry(LocaleRegistry)","sig":"public void SetRegistry(LocaleRegistry newRegistry)","kind":"method","name":"SetRegistry","static":false,"comment":null},{"id":"Rebuild()","sig":"public void Rebuild()","kind":"method","name":"Rebuild","static":false,"comment":"Re-reads every LocaleAsset in the registry. DISCARDS anything added by AddOrOverrideLocale — call it only when the registry itself changed, then re-apply runtime files."},{"id":"AddOrOverrideLocale(string, string, IDictionary<string, string>)","sig":"public void AddOrOverrideLocale(string localeCode, string displayName, IDictionary<string, string> strings)","kind":"method","name":"AddOrOverrideLocale","static":false,"comment":"Adds a language that has no asset at all, or layers text on top of one that does — this is how LocalizationFileLoader feeds a CSV/JSON read at runtime (a community translation, a hotfix wording change) into the same lookup the shipped assets use. Existing keys are overwritten, untouched keys are left alone, so a patch file only needs the lines it actually changes."}],"src_enumValues":[],"src_selfTest":null,"src_demoScene":["Localization_Demo"],"entryKind":"tool","status":"published","summary":"Key-to-text localisation: one CSV or JSON in, every label in the game switches language.","src_uses":["LocaleAsset","LocaleChangedEvent","LocaleRegistry","LocalizationFileLoader","LocalizedText","MissingKeyDisplay","SaveSystem","Singleton<T>"],"src_usedBy":["LocaleAsset","LocaleChangedEvent","LocaleEntry","LocaleRegistry","LocalizationFileFormat","LocalizationFileLoader","LocalizationFileLocation","LocalizationLoadedEvent"],"src_extensionPoints":[],"parts":[{"id":"missing-key-display","name":"MissingKeyDisplay","cat":"Data","src_typeKind":"enum","src_ns":"Toolkit.Data.Localization","src_file":"Data/Localization/LocalizationManager.cs","src_lines":[12,17],"src_base":null,"src_implements":[],"src_static":false,"src_internal":false,"src_runtime":true,"src_attributes":{},"src_typeComment":"What a key that has no translation ANYWHERE should render as. The default is deliberately the loud one: a missing string that silently renders as plausible text is the easiest localisation bug to ship.","src_serialized":[],"src_members":[],"src_enumValues":["Key","MarkedKey","Empty"],"src_selfTest":null,"src_demoScene":[],"entryKind":"enum","status":"skeleton","summary":"What a key that has no translation ANYWHERE should render as.","src_uses":["LocaleAsset","LocaleChangedEvent","LocaleRegistry","LocalizationFileLoader","LocalizationManager","LocalizedText","SaveSystem","Singleton<T>"],"src_usedBy":["LocaleChangedEvent","LocalizationManager"],"src_extensionPoints":[],"foldedInto":"localization-manager"},{"id":"locale-changed-event","name":"LocaleChangedEvent","cat":"Data","src_typeKind":"class","src_ns":"Toolkit.Data.Localization","src_file":"Data/Localization/LocalizationManager.cs","src_lines":[20,20],"src_base":"UnityEvent<string>","src_implements":[],"src_static":false,"src_internal":false,"src_runtime":true,"src_attributes":{},"src_typeComment":"","src_serialized":[],"src_members":[],"src_enumValues":[],"src_selfTest":null,"src_demoScene":[],"entryKind":"tool","status":"skeleton","summary":"","src_uses":["LocaleAsset","LocaleRegistry","LocalizationFileLoader","LocalizationManager","LocalizedText","MissingKeyDisplay","SaveSystem","Singleton<T>"],"src_usedBy":["LocalizationManager","MissingKeyDisplay"],"src_extensionPoints":[],"foldedInto":"localization-manager"}],"isSystem":true,"systemOf":"LocalizationManager","systemPrimaryId":"localization-manager","systemSections":[{"title":"Language data","entries":[{"id":"locale-asset","name":"LocaleAsset","cat":"Data","src_typeKind":"class","src_ns":"Toolkit.Data.Localization","src_file":"Data/Localization/LocaleAsset.cs","src_lines":[31,103],"src_base":"GameDataAsset","src_implements":[],"src_static":false,"src_internal":false,"src_runtime":true,"src_attributes":{"createAssetMenu":"menuName = \"Toolkit/Localization/Locale\", fileName = \"Locale_en\""},"src_typeComment":"One language, as an asset: a locale code (the inherited `id` field — \"en\", \"fr\", \"de\", \"en-PT\"), a human-readable name for a language picker, and a flat key -> text table.  This is a GameDataAsset subclass on purpose: LocaleRegistry is a GameDataRegistry<LocaleAsset>, so looking a language up by its code is the registry's existing GetById() and nothing new had to be written for it. ONE ASSET PER LANGUAGE, not one per string — a per-string asset would mean thousands of .asset files and a merge conflict on every translation pass.","src_serialized":[{"name":"displayName","type":"string","default":"\"\"","tooltip":"Shown to the player in a language picker, in that language — \"English\", \"Français\", \"Deutsch\". The inherited Id above is the code the game uses internally.","header":null,"range":null,"order":0,"comment":null},{"name":"systemLanguage","type":"SystemLanguage","default":"SystemLanguage.Unknown","tooltip":"Which Application.systemLanguage this locale serves. Set it and LocalizationManager can pick this language automatically on a player's first launch. Leave Unknown to opt out of auto-detection — the code is never guessed from the id, so a non-standard code like \"en-PT\" cannot be mis-detected.","header":null,"range":null,"order":1,"comment":null},{"name":"fontOverride","type":"TMP_FontAsset","default":null,"tooltip":"Optional. A font asset to swap in while this locale is active — the practical answer to a language whose glyphs the default font does not contain. LocalizedText applies it automatically.","header":null,"range":null,"order":2,"comment":null},{"name":"entries","type":"List<LocaleEntry>","default":"new List<LocaleEntry>()","tooltip":"The translation table. Normally filled in by the CSV/JSON importer (Toolkit > Localization Importer) rather than typed by hand.","header":null,"range":null,"order":3,"comment":null}],"src_members":[{"id":"DisplayName","sig":"public string DisplayName => string.IsNullOrEmpty(displayName) ? Id : displayName","kind":"property","name":"DisplayName","static":false,"comment":null},{"id":"TargetSystemLanguage","sig":"public SystemLanguage TargetSystemLanguage => systemLanguage","kind":"property","name":"TargetSystemLanguage","static":false,"comment":null},{"id":"FontOverride","sig":"public TMP_FontAsset FontOverride => fontOverride","kind":"property","name":"FontOverride","static":false,"comment":null},{"id":"Entries","sig":"public IReadOnlyList<LocaleEntry> Entries => entries","kind":"property","name":"Entries","static":false,"comment":null},{"id":"TryGet(string, out string)","sig":"public bool TryGet(string key, out string value)","kind":"method","name":"TryGet","static":false,"comment":null},{"id":"Has(string)","sig":"public bool Has(string key)","kind":"method","name":"Has","static":false,"comment":null},{"id":"Count","sig":"public int Count","kind":"property","name":"Count","static":false,"comment":null},{"id":"ToDictionary()","sig":"public Dictionary<string, string> ToDictionary()","kind":"method","name":"ToDictionary","static":false,"comment":"A copy, so LocalizationManager can merge runtime-loaded text on top of it without editing the asset (which would dirty it in the Editor and persist a runtime-only override into source control)."}],"src_enumValues":[],"src_selfTest":null,"src_demoScene":[],"entryKind":"tool","status":"published","summary":"One language, as an asset: a locale code, a display name, and its key-to-text table.","overview":["ONE ASSET PER LANGUAGE — not one per string. An English game with 400 lines and three translations is four assets, not sixteen hundred. Create one with Assets ▸ Create ▸ Toolkit ▸ Localization ▸ Locale, or let the Localization Importer create them from a sheet, which is the normal way.","It extends GameDataAsset, and that is where the locale code lives: THE INHERITED Id FIELD IS THE CODE. It is drawn at the very top of the Inspector, above everything listed here, which is exactly why it gets left blank. It is also the reason LocaleRegistry can be a plain GameDataRegistry<LocaleAsset> with no lookup code of its own."],"useCases":["Holding one language's translations as a versioned asset rather than a loose file.","Giving a language a font of its own, for a script the project font cannot draw.","Letting a language be auto-selected on a device set to that language."],"params":[{"field":"displayName","why":"What a language picker shows the player. Write it IN that language — \"Français\", not \"French\" — because the person who needs to find it cannot yet read the current one.","tuning":"Optional. Left blank, DisplayName falls back to the Id, so a picker shows \"fr\" rather than an empty row. A CSV import fills it with the code; a JSON bundle import fills it properly, because a bundle has a field for it."},{"field":"systemLanguage","why":"Which UnityEngine.SystemLanguage this locale serves. Set it and the manager can pick this language on a player's first launch, with no picker involved.","tuning":"Optional, and Unknown (the default) means \"never auto-select this one\" — which is the correct setting for a joke or test locale. The code is never guessed from the Id, deliberately: that is what stops a made-up code like \"en-PT\" being matched to a real device language by accident."},{"field":"fontOverride","why":"A TMP_FontAsset to swap in while this locale is active. LocalizedText applies it automatically.","tuning":"Optional, and the answer to the most common surprise in localisation: Unity's default LiberationSans SDF is a STATIC atlas of about 250 characters, so Latin-1 languages render and Chinese, Japanese, Korean, Arabic, Hebrew, Thai and Cyrillic come out as empty boxes. Build a font asset with the right character set, drop it here, done. No import ever touches this field."},{"field":"entries","why":"The translation table: one key plus its text per row.","tuning":"Normally written by the Localization Importer rather than typed. Editing by hand is fine — OnValidate drops the cached lookup so a change takes effect immediately. A row with an EMPTY text is treated as untranslated and skipped entirely, so the fallback locale answers instead of a blank label rendering; a duplicated key keeps the first row and warns."}],"apiNotes":{"DisplayName":"Falls back to the Id when the display name is blank, so a language picker never shows an empty row.","TargetSystemLanguage":"Named Target-, not SystemLanguage, because a property with the same name as its type shadows that type inside the class. Unknown means this locale opts out of auto-detection.","Count":"Counts what is actually USABLE — entries with empty text and duplicate keys are excluded, so this is the number a translation-progress readout wants.","ToDictionary()":"Returns a COPY. That is what lets LocalizationManager layer runtime-loaded text on top of a language without dirtying the .asset on disk and committing a runtime patch into source control."},"gotchas":[{"title":"The locale code is the INHERITED Id field, not something on this component","body":"It is drawn above Display Name in the Inspector and belongs to GameDataAsset, so it reads as boilerplate and gets left blank. A locale with no Id is skipped at startup — the language simply will not appear, and the only sign is one console warning naming the asset."},{"title":"Empty text means untranslated, not empty string","body":"Blank entries are excluded from the lookup so the fallback locale can answer. If you genuinely want a key to render as nothing, give it a single space — an empty cell will always defer to the fallback."},{"title":"Creating the asset is not enough — it has to be in the registry","body":"LocalizationManager only ever reads the LocaleRegistry it was given. An orphan LocaleAsset sitting in the project is invisible to the game."}],"seeAlso":["LocaleRegistry","GameData","Localization"],"walkthrough":[{"group":"Inherited from GameDataAsset — drawn ABOVE the fields in the Parameters table","name":"Id","what":"REQUIRED, and the field people miss. This is the locale CODE — \"en\", \"fr\", \"pt-BR\" — and it is what SetLocale(\"fr\") matches and what the registry looks up. Any string works; stick to the usual ISO codes unless you have a reason not to. A blank Id means the language is skipped at startup, with one console warning naming the asset. Two assets sharing a code: the first wins, also with a warning."}],"src_uses":["GameDataAsset","GameDataRegistry<T>","LocaleEntry","LocaleRegistry","LocalizationManager","LocalizedText"],"src_usedBy":["LocaleBundle","LocaleBundleEntry","LocaleChangedEvent","LocaleEntry","LocaleRegistry","LocalizationBundleJson","LocalizationEditorWindow","LocalizationImporterWindow"],"src_extensionPoints":[],"parts":[{"id":"locale-entry","name":"LocaleEntry","cat":"Data","src_typeKind":"class","src_ns":"Toolkit.Data.Localization","src_file":"Data/Localization/LocaleAsset.cs","src_lines":[13,21],"src_base":null,"src_implements":[],"src_static":false,"src_internal":false,"src_runtime":true,"src_attributes":{},"src_typeComment":"One row of a locale's translation table. A class rather than a struct so Unity's Inspector gives it proper reorderable-list behaviour, and [TextArea] so a long sentence doesn't have to be edited through a one-line field.","src_serialized":[],"src_members":[{"id":"key","sig":"public string key","kind":"field","name":"key","static":false,"comment":null},{"id":"text","sig":"public string text","kind":"field","name":"text","static":false,"comment":null}],"src_enumValues":[],"src_selfTest":null,"src_demoScene":[],"entryKind":"tool","status":"skeleton","summary":"One row of a locale's translation table.","src_uses":["GameDataAsset","GameDataRegistry<T>","LocaleAsset","LocaleRegistry","LocalizationManager","LocalizedText"],"src_usedBy":["LocaleAsset","LocalizationEditorWindow","LocalizedTextEditor"],"src_extensionPoints":[],"foldedInto":"locale-asset"}]},{"id":"locale-registry","name":"LocaleRegistry","cat":"Data","src_typeKind":"class","src_ns":"Toolkit.Data.Localization","src_file":"Data/Localization/LocaleRegistry.cs","src_lines":[13,15],"src_base":"GameDataRegistry<LocaleAsset>","src_implements":[],"src_static":false,"src_internal":false,"src_runtime":true,"src_attributes":{"createAssetMenu":"menuName = \"Toolkit/Localization/Locale Registry\", fileName = \"LocaleRegistry\""},"src_typeComment":"The list of every language the game ships with. This is the concrete subclass GameDataRegistry<T>'s own comment asks for — Unity cannot put [CreateAssetMenu] on a generic type, so the pattern is to subclass it once per data type. Nothing else is needed: GetById(\"fr\") and All come from the base class.  Assign one of these to LocalizationManager and every LocaleAsset in its list becomes a selectable language.","src_serialized":[],"src_members":[],"src_enumValues":[],"src_selfTest":null,"src_demoScene":[],"entryKind":"tool","status":"published","summary":"The list of every language the game ships with. A GameDataRegistry<LocaleAsset> and nothing more.","overview":["The single asset you hand LocalizationManager. It holds every LocaleAsset, and looking a language up by its code is the base class's own GetById — there is no code in this file at all beyond the [CreateAssetMenu] line, which is the point: GameDataRegistry<T> already solved this, and a language keyed by a locale code is exactly the shape it solves."],"useCases":["Giving the manager one reference instead of a list of language assets.","Adding a language to a shipped game by dropping its asset into this list.","Keeping a language out of a build by removing it here, without deleting its asset."],"gotchas":[{"title":"The registry is the only place the manager looks","body":"A LocaleAsset that exists in the project but is not listed here does not exist as far as the game is concerned. This is the most common reason a language you just imported does not show up."},{"title":"Create it via the importer, not by hand, unless you want to wire it yourself","body":"Toolkit > Localization Importer creates the registry and fills it as part of an import. Assets > Create > Toolkit > Localization > Locale Registry makes an empty one you then populate by dragging."}],"seeAlso":["LocaleAsset","GameData","Localization"],"walkthrough":[{"group":"Inherited from GameDataRegistry<LocaleAsset> — this asset declares no fields of its own","name":"Entries","what":"ORDER MATTERS in two places: AvailableLocaleCodes returns this order, so it is the order a language picker will show; and first-run system-language detection scans it top to bottom, so the first matching locale wins. An empty slot or a duplicate code is warned about and skipped, not thrown on. A re-import appends new languages and never reorders or removes existing ones."}],"src_uses":["GameDataRegistry<T>","LocaleAsset","LocalizationManager"],"src_usedBy":["LocaleAsset","LocaleChangedEvent","LocaleEntry","LocalizationEditorWindow","LocalizationImporterWindow","LocalizationManager","LocalizationSceneSetup","LocalizedTextEditor"],"src_extensionPoints":[]},{"id":"localized-string-asset","name":"LocalizedStringAsset","cat":"Data","src_typeKind":"class","src_ns":"Toolkit.Data.Localization","src_file":"Data/Localization/LocalizedStringAsset.cs","src_lines":[27,61],"src_base":"ScriptableObject","src_implements":[],"src_static":false,"src_internal":false,"src_runtime":true,"src_attributes":{"createAssetMenu":"menuName = \"Toolkit/Localization/Localized String\", fileName = \"Key_NewString\""},"src_typeComment":"A key you DRAG instead of a key you TYPE.  The problem it solves: a localisation key is a magic string. Type \"menu.strat\" instead of \"menu.start\" and nothing complains until a screenshot shows #menu.strat#; rename a key in the sheet and every scene that typed the old one silently breaks, with no reference anywhere to find. Point LocalizedText at one of these assets instead and the key lives in exactly ONE place — rename it here, or rename it in the Localization Editor, and every user of it follows.  Same idea as the toolkit's ScriptableVariable/GameEvent assets: several unrelated objects agree by pointing at one asset rather than by repeating a literal at each site.  ENTIRELY OPTIONAL. LocalizedText still takes a plain string key, and that is still the right choice for a one-off label or a key built at runtime. Create these for the keys you reference from scenes and inspectors often enough that a typo would cost you — or let the Localization Importer generate one per key in a registry, in one pass.  WHY THIS IS NOT A GameDataAsset, unlike LocaleAsset: GameDataAsset exists to be LOOKED UP BY ID out of a GameDataRegistry, which is exactly what a language needs and exactly what a key does not — a key asset is referenced directly by the field that drags it, never searched for. Inheriting would have bought nothing and re-inflicted the one genuinely confusing thing about LocaleAsset: an `id` field on the base class, drawn above everything else, that you have to know is really the code.","src_serialized":[{"name":"key","type":"string","default":"\"\"","tooltip":"The lookup key this asset stands for, e.g. \"menu.start\". Change it here and every LocalizedText pointing at this asset follows — that is the entire point.","header":null,"range":null,"order":0,"comment":null},{"name":"context","type":"string","default":"\"\"","tooltip":"Optional note for whoever edits the translations — where this line appears, how much room it has, who is speaking. Never shown to a player.","header":null,"range":null,"order":1,"comment":null}],"src_members":[{"id":"Key","sig":"public string Key => key","kind":"property","name":"Key","static":false,"comment":null},{"id":"Context","sig":"public string Context => context","kind":"property","name":"Context","static":false,"comment":null},{"id":"Value","sig":"public string Value","kind":"property","name":"Value","static":false,"comment":"Convenience so a plain C# caller can hold one of these instead of a string and never touch the manager directly. Returns the key itself when there is no manager yet (in the Editor, outside Play mode) rather than throwing, so an inspector or a tool can call it safely."},{"id":"Format(params object[])","sig":"public string Format(params object[] args)","kind":"method","name":"Format","static":false,"comment":null},{"id":"SetKey(string)","sig":"public void SetKey(string newKey) => key = newKey","kind":"method","name":"SetKey","static":false,"comment":"Used by the Localization Editor's rename, which has to update every asset pointing at the old key. Editor-only in practice, but not #if'd: a runtime tool that builds keys is a legitimate thing to write, and an #if UNITY_EDITOR here would make this asset behave differently in a build."}],"src_enumValues":[],"src_selfTest":null,"src_demoScene":[],"entryKind":"tool","status":"published","summary":"A key you DRAG instead of a key you type. Optional, and mixable with typed keys.","overview":["A localisation key is a magic string. Type \"menu.strat\" instead of \"menu.start\" and nothing complains until a screenshot shows #menu.strat#; rename a key in the sheet and every scene that typed the old one silently breaks, with no reference anywhere to find them. Point LocalizedText at one of these assets instead and the key lives in exactly ONE place — rename it here, or in the Localization Editor, and every user of it follows.","Same idea as the toolkit's ScriptableVariable and GameEvent assets: several unrelated objects agree by pointing at one asset rather than by repeating a literal at each site.","ENTIRELY OPTIONAL, and the two styles mix freely in one project. A typed key is still right for a one-off label or a key decided at runtime. Create these for the keys you reference often enough that a typo would cost you — or let the Localization Importer generate one per key in a registry, in a single pass."],"useCases":["A key used by several labels, or one you expect to rename.","Letting a designer wire a label by dragging, with no chance of a typo.","Finding every user of a key — select the asset and use Find References.","Holding a key in plain C# without holding a string, via Value and Format."],"params":[{"field":"key","why":"REQUIRED. The lookup key this asset stands for, e.g. \"menu.start\".","tuning":"Change it here and every LocalizedText pointing at this asset follows — that is the entire point of the asset existing. The Localization Editor's rename does this for you across the locales and the key assets together, which is the safer way to do it."},{"field":"context","why":"A note for whoever edits the translations: where this line appears, how much room it has, who is speaking.","tuning":"Optional and never shown to a player. It is displayed under the field on any LocalizedText using this asset, which is where a translator-facing note is actually useful."}],"usage":{"code":"// The normal use is drag-and-drop in the Inspector, with no code at all.\n\n// In code, a field can hold the asset rather than a string — so a typo cannot\n// compile and Find References works:\n[SerializeField] private LocalizedStringAsset notEnoughGold;\n\nToastNotification.Instance.Show(notEnoughGold.Value);\nstatusLabel.text = coinsLine.Format(coinsHeld, coinsTotal);","codeNote":"Value and Format fall back to returning the key itself when there is no LocalizationManager yet — safe to call from an editor tool or outside Play mode rather than throwing."},"apiNotes":{"Key":"What LocalizedText actually looks up. Reading this rather than storing a copy is what makes a rename take effect everywhere at once.","Value":"The current language's text for this key, straight from the manager. Returns the key itself when no manager exists yet, so an inspector or editor tool can call it safely.","Format(params object[])":"Value plus string.Format, for a key whose text contains {0}, {1}. Same broken-format-string protection as the manager: a bad translation returns the template rather than throwing.","SetKey(string)":"Deliberately NOT editor-only. The Localization Editor's rename uses it, but a runtime tool that builds keys is a legitimate thing to write, and an #if UNITY_EDITOR here would make the asset behave differently in a build."},"gotchas":[{"title":"The asset WINS over a typed key on the same component","body":"When both are set, LocalizedText uses the asset and the typed Key field is inert — the inspector greys it out and says so. The rule is deliberately not \"whichever is non-empty\": a half-migrated label with a stale typed key and an asset has to behave predictably. Note the matching consequence in code: SetKey(string) CLEARS the asset, or it would appear to do nothing."},{"title":"It is not a GameDataAsset, unlike LocaleAsset","body":"GameDataAsset exists to be looked up by Id out of a GameDataRegistry — exactly what a language needs and exactly what a key does not, since a key asset is referenced directly by the field that drags it. Inheriting would have bought nothing and re-inflicted the one genuinely confusing thing about LocaleAsset: an inherited `id` field, drawn above everything else, that you have to know is really the code."},{"title":"Generating assets does not validate them","body":"The importer generates one asset per key that exists in the registry AT THAT MOMENT. Rename a key in the sheet afterwards and the old asset still holds the old key — it will resolve to nothing. Re-generating reports those as orphans rather than deleting them, because they are usually the trail back to references you need to fix."}],"seeAlso":["LocalizedText","Localization","ScriptableVariables","GameEvent"],"src_uses":["GameDataAsset","GameDataRegistry<T>","GameEvent","LocaleAsset","LocalizationManager","LocalizedText","ScriptableVariable<T>"],"src_usedBy":["LocalizationEditorWindow","LocalizationImporterWindow","LocalizedText","LocalizedTextEditor"],"src_extensionPoints":[]}]},{"title":"In the scene","entries":[{"id":"localized-text","name":"LocalizedText","cat":"Data","src_typeKind":"class","src_ns":"Toolkit.Data.Localization","src_file":"Data/Localization/LocalizedText.cs","src_lines":[20,143],"src_base":"MonoBehaviour","src_implements":[],"src_static":false,"src_internal":false,"src_runtime":true,"src_attributes":{"addComponentMenu":"Toolkit/Localization/Localized Text"},"src_typeComment":"Drop this on any label, type a key, and it shows that key's text in the current language — and swaps the instant the language changes. This is the component you actually use day to day; everything else in the folder exists to feed it.  The target label is found on this same GameObject if you do not assign one, so the whole setup is \"Add Component, type key\". Both TextMeshPro and legacy UI.Text are supported because a project that predates TMP should not have to migrate its UI before it can be translated.  TWO WAYS TO NAME THE KEY, and you can mix them freely in one project: * TYPE it into Key — quickest, right for a one-off label or a key decided at runtime. * DRAG a LocalizedStringAsset into Key Asset — the key then lives in one asset, so renaming it updates every label at once and a typo is impossible. The asset WINS when both are set.","src_serialized":[{"name":"keyAsset","type":"LocalizedStringAsset","default":null,"tooltip":"OPTIONAL. Drag a Localized String asset here instead of typing a key below. The asset WINS if set, and it is the drag-and-drop option: rename the key in one place and every label using it follows.","header":null,"range":null,"order":0,"comment":null},{"name":"key","type":"string","default":null,"tooltip":"The lookup key, e.g. \"ui.start_button\", when you are not using a Localized String asset. The same key exists in every locale — that is what makes switching language work.","header":null,"range":null,"order":1,"comment":null},{"name":"tmpTarget","type":"TMP_Text","default":null,"tooltip":"Optional. Leave empty and the TextMeshPro or UI.Text component on this GameObject is used.","header":null,"range":null,"order":2,"comment":null},{"name":"uiTarget","type":"Text","default":null,"tooltip":"Optional. A legacy UI.Text target, for projects not on TextMeshPro. Only used when there is no TMP target.","header":null,"range":null,"order":3,"comment":null},{"name":"applyLocaleFont","type":"bool","default":"true","tooltip":"Apply the active locale's Font Override (if it has one) to this label. Turn off for a label whose font is deliberately fixed, like a logo.","header":null,"range":null,"order":4,"comment":null}],"src_members":[{"id":"Key","sig":"public string Key => keyAsset != null ? keyAsset.Key : key","kind":"property","name":"Key","static":false,"comment":"The asset wins when both are set. Deliberately not \"whichever is non-empty\": a half-migrated label with a stale typed key AND an asset must behave predictably, and \"the asset is the source of truth\" is the rule that is easy to state and easy to see in the inspector, which greys the string out."},{"id":"KeyAsset","sig":"public LocalizedStringAsset KeyAsset => keyAsset","kind":"property","name":"KeyAsset","static":false,"comment":null},{"id":"SetKey(string)","sig":"public void SetKey(string newKey)","kind":"method","name":"SetKey","static":false,"comment":"Swap which line this label shows — e.g. one reusable status label that says \"Saved\" or \"Failed\".  CLEARS the asset reference, because otherwise the asset would keep winning and this call would silently do nothing — the single most confusing thing this hybrid could have done."},{"id":"SetKeyAsset(LocalizedStringAsset)","sig":"public void SetKeyAsset(LocalizedStringAsset newKeyAsset)","kind":"method","name":"SetKeyAsset","static":false,"comment":"NOT an overload of SetKey, deliberately: SetKey(null) would then be ambiguous between a string and an asset and would not compile at the call site — a trap set for whoever writes the clearing code six months from now. A separate name costs nothing and cannot be ambiguous."},{"id":"SetArguments(params object[])","sig":"public void SetArguments(params object[] args)","kind":"method","name":"SetArguments","static":false,"comment":"Supply the values for a key whose text contains {0}, {1}, ... They are remembered, so the label re-formats itself correctly when the player switches language without the caller doing anything."},{"id":"ClearArguments()","sig":"public void ClearArguments()","kind":"method","name":"ClearArguments","static":false,"comment":null},{"id":"Refresh()","sig":"public void Refresh()","kind":"method","name":"Refresh","static":false,"comment":null}],"src_enumValues":[],"src_selfTest":null,"src_demoScene":["Localization_Demo"],"entryKind":"tool","status":"published","summary":"Put it on a label, type a key, and the text follows the current language forever after.","overview":["The component you actually use. Everything else in the folder exists to feed this one. Add it beside a TextMeshPro label, type a key, and that label shows the key's text in the current language and rewrites itself the moment the language changes — no code, no manual refresh, nothing to subscribe to.","TWO WAYS TO NAME THE KEY, mixable in one project: TYPE it into Key — quickest, and right for a one-off label or a key decided at runtime — or DRAG a LocalizedStringAsset into Key Asset, so the key lives in one place and renaming it reaches every label at once. The ASSET WINS when both are set."],"useCases":["Every piece of fixed UI text in the game: menu items, button labels, headings, tooltips.","A line with a value in it — \"You have {0} coins\" — where the value comes from the game and the wording comes from the language.","One reusable status label that shows different lines at different times, via SetKey."],"params":[{"field":"keyAsset","why":"OPTIONAL. Drag a LocalizedStringAsset here instead of typing a key.","tuning":"When set it WINS over the typed Key, and the inspector greys that field out and shows which key the asset holds. Use it for keys you might rename or that several labels share; a typed key is still right for a one-off. The Localization Importer can generate one asset per key in a single pass."},{"field":"key","why":"REQUIRED. The lookup key, e.g. \"menu.start\". The same key exists in every language — that is what makes switching work.","tuning":"Leave it EMPTY and the component does nothing at all: the label keeps whatever text it was authored with, no warning. That is deliberate, so a half-built screen is not covered in markers, but it also means a forgotten key looks exactly like a working one. Ignored entirely while a Key Asset is assigned. The inspector's Pick Key button lists the keys that really exist, and previews the text in every language underneath."},{"field":"tmpTarget","why":"The TextMeshPro label to write into.","tuning":"Optional. Left empty, the component looks for a TMP_Text on ITS OWN GameObject — not on children. On a Button, that means this component belongs on the Label child, not on the Button."},{"field":"uiTarget","why":"A legacy UnityEngine.UI.Text target, for a project not on TextMeshPro.","tuning":"Optional, and only used when there is no TMP target. Auto-found the same way. If neither exists on the GameObject you get one console warning naming the object, rather than silence."},{"field":"applyLocaleFont","why":"Apply the active language's Font Override to this label, if it has one.","tuning":"On by default, which is what you want for body text. Turn it OFF for a label whose font is deliberately fixed — a logo, a stylised title — so a CJK font swap does not flatten it."}],"usage":{"code":"// The normal case needs no code: add the component, type the key.\n\n// A line that takes values. Set them ONCE — they are remembered and re-applied\n// on every language change, so you never call this again just because the\n// player switched language:\ngreetingLabel.SetArguments(playerName);\nscoreLabel.SetArguments(coinsHeld, coinsTotal);\n\n// Reuse one label for different lines:\nstatusLabel.SetKey(\"status.saved\");\nstatusLabel.SetKey(\"status.failed\");","codeNote":"The key's text in that language must contain {0}, {1} and so on for the arguments to land anywhere. If a translator breaks the placeholders, the raw template is shown and the key is named in the console."},"apiNotes":{"SetArguments(params object[])":"Stored, not applied once. That is the difference that matters: a formatted label survives a language switch without the caller doing anything, because Refresh re-formats from the stored values every time.","SetKey(string)":"Swaps which line this label shows and refreshes immediately. It also CLEARS any key asset — otherwise the asset would keep winning and the call would silently do nothing.","Refresh()":"Re-reads the current language. Called for you on enable and on every language change; you only need it after changing something the component cannot see.","Key":"The RESOLVED key: the asset's key when one is assigned, otherwise the typed string. Read-only, and what a tool or test should check rather than either field.","SetKeyAsset(LocalizedStringAsset)":"Points the label at a key asset from code. Deliberately NOT an overload of SetKey: SetKey(null) would then be ambiguous between a string and an asset and would fail to compile at the call site."},"gotchas":[{"title":"When both a key asset and a typed key are set, the ASSET wins","body":"Not \"whichever is non-empty\": a half-migrated label carrying a stale typed key and an asset has to behave predictably, and \"the asset is the source of truth\" is the rule that is easy to state and visible in the inspector. The matching consequence in code is that SetKey(string) clears the asset."},{"title":"It writes to a text component on its OWN GameObject, not a child","body":"Auto-detection is GetComponent, not GetComponentInChildren — deliberately, so a panel full of labels cannot accidentally all bind to the first one. On a Button, put this on the Label child."},{"title":"An empty key is silent","body":"No key means no work and no warning, so a label you forgot to fill in looks identical to one that is working. Use the inspector preview to check: it shows the text in every language, and warns when a key resolves nowhere."},{"title":"Arguments live on the component, not in the key","body":"Two labels showing the same key can hold different arguments. Equally, a label whose key has no placeholders ignores its arguments entirely rather than erroring."}],"seeAlso":["LocalizedStringAsset","Localization","LocaleAsset"],"src_uses":["LocalizationManager","LocalizedStringAsset","Singleton<T>"],"src_usedBy":["LocaleAsset","LocaleChangedEvent","LocaleEntry","LocalizationEditorWindow","LocalizationImporterWindow","LocalizationManager","LocalizationSceneSetup","LocalizedStringAsset"],"src_extensionPoints":[]},{"id":"localization-file-loader","name":"LocalizationFileLoader","cat":"Data","src_typeKind":"class","src_ns":"Toolkit.Data.Localization","src_file":"Data/Localization/LocalizationFileLoader.cs","src_lines":[37,156],"src_base":"MonoBehaviour","src_implements":[],"src_static":false,"src_internal":false,"src_runtime":true,"src_attributes":{"addComponentMenu":"Toolkit/Localization/Localization File Loader"},"src_typeComment":"OPTIONAL. Loads a translation file at runtime and layers it over the locales the game shipped with — the answer to \"we found a typo in the German text\" or \"a player translated it into Polish\" without rebuilding. Delete this script if you only ever want the LocaleAssets that ship in the registry; nothing else in the folder depends on it.  Keys that the file does not mention are left alone, so a patch file only needs the lines it changes, and a CSV can introduce a language that has no asset at all.","src_serialized":[{"name":"format","type":"LocalizationFileFormat","default":"LocalizationFileFormat.Csv","tooltip":"Csv = one sheet, a column per language. Json = one flat { key: text } file holding ONE language. JsonBundle = one readable file holding EVERY language, and the only format that can also supply display names.","header":null,"range":null,"order":0,"comment":null},{"name":"location","type":"LocalizationFileLocation","default":"LocalizationFileLocation.StreamingAssets","tooltip":"Where the file lives. StreamingAssets ships with the build; PersistentDataPath is for a file downloaded or dropped in after install.","header":null,"range":null,"order":1,"comment":null},{"name":"filePath","type":"string","default":"\"Localization/extra.csv\"","tooltip":"Path within that location, e.g. \"Localization/extra.csv\". For Absolute Path, the full path including the file name.","header":null,"range":null,"order":2,"comment":null},{"name":"jsonLocaleCode","type":"string","default":"\"en\"","tooltip":"Json format ONLY: the locale code this file's text belongs to. Ignored by Csv (which names its languages in the header) and by JsonBundle (which names them per entry).","header":null,"range":null,"order":3,"comment":null},{"name":"jsonDisplayName","type":"string","default":"\"\"","tooltip":"Json format ONLY: the name to show in a language picker if this file introduces a brand-new locale. Ignored by Csv (no column for it) and by JsonBundle (which carries its own).","header":null,"range":null,"order":4,"comment":null},{"name":"loadOnStart","type":"bool","default":"true","tooltip":"Load as soon as this component starts. Turn off to call Load() yourself at a controlled moment.","header":null,"range":null,"order":5,"comment":null},{"name":"activateAfterLoad","type":"bool","default":"false","tooltip":"After loading, switch the game to the first locale the file provided. Useful when the file IS the language the player asked for; leave off when it is just a patch.","header":null,"range":null,"order":6,"comment":null}],"src_members":[{"id":"LocalizationLoadedEvent()","sig":"public LocalizationLoadedEvent OnLoaded = new LocalizationLoadedEvent()","kind":"method","name":"LocalizationLoadedEvent","static":false,"comment":null},{"id":"IsLoaded","sig":"public bool IsLoaded { get; private set; }","kind":"property","name":"IsLoaded","static":false,"comment":null},{"id":"LoadedKeyCount","sig":"public int LoadedKeyCount { get; private set; }","kind":"property","name":"LoadedKeyCount","static":false,"comment":null},{"id":"LastError","sig":"public string LastError { get; private set; } = \"\"","kind":"property","name":"LastError","static":false,"comment":null},{"id":"Load()","sig":"public void Load() => StartCoroutine(LoadRoutine())","kind":"method","name":"Load","static":false,"comment":null},{"id":"Apply(string)","sig":"public void Apply(string fileText)","kind":"method","name":"Apply","static":false,"comment":"Exposed separately so text fetched some other way — a web response, an in-game text box, a test — can go through exactly the same merge path as a file on disk."}],"src_enumValues":[],"src_selfTest":null,"src_demoScene":["Localization_Demo"],"entryKind":"tool","status":"published","summary":"Optional: reads a translation file at Play time and layers it over the languages the game shipped with.","overview":["The answer to \"we found a typo in the German text\" and \"a player translated it into Polish\" without a rebuild. Drop it in the scene, point it at a file, and its text is merged into the same lookup the shipped LocaleAssets use. Keys the file does not mention are left alone, so a patch file only needs the lines it actually changes — and a file can introduce a language that has no asset at all.","Entirely optional. Delete the script if you only ever want the languages in the registry; nothing else in the folder depends on it."],"useCases":["Patching wording in a shipped build without shipping a new build.","Accepting a community translation as a file the player drops in.","Downloading a language pack after install, into persistentDataPath.","Iterating on wording during development without re-importing assets."],"params":[{"field":"format","why":"Which of the three file shapes this is.","tuning":"Csv reads a sheet with a column per language. Json reads one flat { key: text } file holding ONE language. JsonBundle reads every language from one readable file and is the only option that can also supply display names — a language introduced by a CSV can only show its own code in a picker."},{"field":"location","why":"Which folder the path is relative to.","tuning":"StreamingAssets ships inside the build and is read-only — right for a file you author. PersistentDataPath is writable after install — right for a download or a file the player supplies. AbsolutePath is mostly for desktop while authoring."},{"field":"filePath","why":"REQUIRED. The path within that location, including the file name.","tuning":"Forward slashes, e.g. \"Localization/extra.csv\". A missing or unreadable file is NOT fatal: it logs a warning, leaves the shipped languages untouched, fires OnLoaded with 0, and records why in LastError."},{"field":"jsonLocaleCode","why":"Json format ONLY: which language this file's text belongs to, since a flat JSON file does not say.","tuning":"Ignored by Csv (the header names the languages) and by JsonBundle (each entry names its own). Point it at the wrong file and the text lands in the wrong language without complaint."},{"field":"jsonDisplayName","why":"Json format ONLY: the picker name to use if this file introduces a brand-new language.","tuning":"Ignored by the other two formats. Leave it empty for a file that only patches a language that already exists."},{"field":"loadOnStart","why":"Read the file as soon as this component starts.","tuning":"On by default. Turn it off and call Load() yourself when you want control over the moment — after a download completes, or once the player has picked a file."},{"field":"activateAfterLoad","why":"Switch the game to the first language the file provided, once it has loaded.","tuning":"Off by default, which is right for a patch file: it should change the wording of whatever language is already active, not yank the player into a different one. Turn it on when the file IS the language the player asked for."}],"usage":{"code":"// Normally nothing: set the fields and leave Load On Start on.\n\n// Controlled timing instead:\nloader.Load();\n\n// Or feed it text you already have — a web response, a paste box, a test.\n// This is the same merge path a real file takes.\nloader.Apply(downloadedText);","codeNote":"OnLoaded fires with the number of keys applied, including 0 when the file was missing — so a UI can report the outcome either way rather than only the happy path."},"apiNotes":{"Apply(string)":"The merge half, split out so text fetched any other way goes through exactly the same path as a file on disk. It is also how the self-test covers this component without a player loop.","Load()":"Starts the coroutine. Safe to call repeatedly; a later file simply layers over an earlier one.","LastError":"Empty after a successful load, otherwise the reason — check this rather than guessing when nothing appeared.","LoadedKeyCount":"How many keys the file actually applied. A file that parsed but contained nothing useful reports 0 here with no error."},"gotchas":[{"title":"It is a coroutine, so the text lands a frame or two after Start","body":"Reading goes through UnityWebRequest rather than File.ReadAllText, because on Android StreamingAssets lives inside the compressed APK where System.IO cannot open it at all. Labels do not need handling for this — the merge fires OnLocaleChanged and every LocalizedText re-reads itself — but code that samples a string in its own Start may see the pre-patch text."},{"title":"LocalizationManager.Rebuild() discards everything this loaded","body":"Rebuild re-reads the registry from scratch. If you call it, re-apply your runtime files afterwards."},{"title":"It never writes to the LocaleAssets","body":"The merge happens in the manager's in-memory copy, so a runtime patch cannot dirty an asset and end up committed to source control by accident. The flip side is that nothing persists: the file is re-read every run."}],"seeAlso":["Localization","LocalizationBundleJson","StreamingAssetLoader"],"src_uses":["LocaleBundle","LocaleBundleEntry","LocalizationBundleJson","LocalizationCsv","LocalizationFileFormat","LocalizationFileLocation","LocalizationJson","LocalizationLoadedEvent"],"src_usedBy":["LocaleChangedEvent","LocalizationFileFormat","LocalizationFileLocation","LocalizationLoadedEvent","LocalizationManager","MissingKeyDisplay"],"src_extensionPoints":[],"parts":[{"id":"localization-file-format","name":"LocalizationFileFormat","cat":"Data","src_typeKind":"enum","src_ns":"Toolkit.Data.Localization","src_file":"Data/Localization/LocalizationFileLoader.cs","src_lines":[10,15],"src_base":null,"src_implements":[],"src_static":false,"src_internal":false,"src_runtime":true,"src_attributes":{},"src_typeComment":"","src_serialized":[],"src_members":[],"src_enumValues":["Csv","Json","JsonBundle"],"src_selfTest":null,"src_demoScene":[],"entryKind":"enum","status":"skeleton","summary":"","src_uses":["LocaleBundle","LocaleBundleEntry","LocalizationBundleJson","LocalizationCsv","LocalizationFileLoader","LocalizationFileLocation","LocalizationJson","LocalizationLoadedEvent"],"src_usedBy":["LocalizationFileLoader","LocalizationFileLocation","LocalizationLoadedEvent"],"src_extensionPoints":[],"foldedInto":"localization-file-loader"},{"id":"localization-file-location","name":"LocalizationFileLocation","cat":"Data","src_typeKind":"enum","src_ns":"Toolkit.Data.Localization","src_file":"Data/Localization/LocalizationFileLoader.cs","src_lines":[17,22],"src_base":null,"src_implements":[],"src_static":false,"src_internal":false,"src_runtime":true,"src_attributes":{},"src_typeComment":"","src_serialized":[],"src_members":[],"src_enumValues":["StreamingAssets","PersistentDataPath","AbsolutePath"],"src_selfTest":null,"src_demoScene":[],"entryKind":"enum","status":"skeleton","summary":"","src_uses":["LocaleBundle","LocaleBundleEntry","LocalizationBundleJson","LocalizationCsv","LocalizationFileFormat","LocalizationFileLoader","LocalizationJson","LocalizationLoadedEvent"],"src_usedBy":["LocalizationFileFormat","LocalizationFileLoader","LocalizationLoadedEvent"],"src_extensionPoints":[],"foldedInto":"localization-file-loader"},{"id":"localization-loaded-event","name":"LocalizationLoadedEvent","cat":"Data","src_typeKind":"class","src_ns":"Toolkit.Data.Localization","src_file":"Data/Localization/LocalizationFileLoader.cs","src_lines":[27,27],"src_base":"UnityEvent<int>","src_implements":[],"src_static":false,"src_internal":false,"src_runtime":true,"src_attributes":{},"src_typeComment":"UnityEvent<T> only shows up in the Inspector through a concrete [Serializable] subclass — Unity cannot serialize an open generic. Without this the event would work from code but be invisible to wire by hand.","src_serialized":[],"src_members":[],"src_enumValues":[],"src_selfTest":null,"src_demoScene":[],"entryKind":"tool","status":"skeleton","summary":"UnityEvent<T> only shows up in the Inspector through a concrete [Serializable] subclass — Unity cannot serialize an...","src_uses":["LocaleBundle","LocaleBundleEntry","LocalizationBundleJson","LocalizationCsv","LocalizationFileFormat","LocalizationFileLoader","LocalizationFileLocation","LocalizationJson"],"src_usedBy":["LocalizationFileFormat","LocalizationFileLoader","LocalizationFileLocation"],"src_extensionPoints":[],"foldedInto":"localization-file-loader"}]}]},{"title":"File formats","entries":[{"id":"localization-csv","name":"LocalizationCsv","cat":"Data","src_typeKind":"class","src_ns":"Toolkit.Data.Localization","src_file":"Data/Localization/LocalizationCsv.cs","src_lines":[46,221],"src_base":null,"src_implements":[],"src_static":true,"src_internal":false,"src_runtime":true,"src_attributes":{},"src_typeComment":"Converts between a translator's spreadsheet and the toolkit's key -> text tables.  THE SHEET SHAPE IS ONE COLUMN PER LANGUAGE, one row per key:  key,en,fr,de ui.start,Start,Démarrer,Starten ui.quit,Quit,Quitter,  which is the shape a translator is actually handed, because every language sits side by side and an untranslated cell is visibly blank. Note this is TRANSPOSED relative to CsvToScriptableObjectImporter, whose columns are FIELDS of one asset per row — that tool cannot read this shape, which is why the localisation importer is its own window. The CSV parsing itself is the existing CsvUtility, so quoted commas and newlines inside a translated sentence are handled here for free.  A blank cell means NOT TRANSLATED, not \"empty string\" — it is skipped entirely so the fallback locale fills the gap. A translator's half-finished sheet is the normal case, not an error.","src_serialized":[],"src_members":[{"id":"DefaultKeyColumnName","sig":"public const string DefaultKeyColumnName = \"key\"","kind":"const","name":"DefaultKeyColumnName","static":false,"comment":null},{"id":"Parse(string, string)","sig":"public static LocalizationTable Parse(string csvText, string keyColumnName = DefaultKeyColumnName)","kind":"method","name":"Parse","static":true,"comment":null},{"id":"ParseRows(IReadOnlyList<string[]>, string)","sig":"public static LocalizationTable ParseRows(IReadOnlyList<string[]> rows, string keyColumnName = DefaultKeyColumnName)","kind":"method","name":"ParseRows","static":true,"comment":null},{"id":"BuildRows(LocalizationTable, string)","sig":"public static List<string[]> BuildRows(LocalizationTable table, string keyColumnName = DefaultKeyColumnName)","kind":"method","name":"BuildRows","static":true,"comment":"The round trip: hand a translator back a sheet containing every key that currently exists, with the translations already done filled in and the rest blank. This is how new keys reach them without anyone diffing asset files by hand."},{"id":"ToCsv(LocalizationTable, string, bool)","sig":"public static string ToCsv(LocalizationTable table, string keyColumnName = DefaultKeyColumnName, bool alignColumns = false)","kind":"method","name":"ToCsv","static":true,"comment":"alignColumns pads each column to a common width so the file reads as a TABLE in a plain text editor instead of a wall of commas — which is the difference between a file you can proofread and one you can only load into a spreadsheet. The padding is plain spaces placed AFTER each comma, so the result is still valid CSV and ParseRows trims it straight back off.  The trade-off, stated plainly: open an aligned file in Excel and the padding shows up as leading spaces inside the cells. Export unaligned when the file is going straight to a translator working in a spreadsheet; export aligned when a person is going to READ it."}],"src_enumValues":[],"src_selfTest":null,"src_demoScene":[],"entryKind":"tool","status":"published","summary":"The translator's sheet: one column per language, one row per key. Read, written and aligned here.","overview":["THE FORMAT, in full — a header row naming the key column and then ONE COLUMN PER LANGUAGE, whose header cell is that language's locale code, followed by one row per key:\n\nkey,          en,                          fr,                              de\ndemo.title,   Localization,                Localisation,                    Lokalisierung\nhud.greeting, \"Welcome back, {0}!\",        \"Bon retour, {0} !\",             \"Willkommen zurück, {0}!\"\nmenu.quit,    Quit,                        Quitter,                         Beenden\nmenu.options, Options,                     Options,\n\nThat is the whole specification. The last row shows the one rule that is not obvious: German has no text for menu.options, so the cell is blank — which means NOT TRANSLATED YET, not \"empty string\". It is skipped entirely, and the fallback language answers instead of a blank label appearing in the game.","This is the shape to hand a translator, because every language sits side by side in a spreadsheet and an unfinished cell is visibly blank. It is a poor shape to read in a text editor, which is what the alignment above is for, and it has nowhere to record a language's display name or its auto-detect language — the JSON bundle format exists for both of those."],"useCases":["Sending a sheet out for translation and importing what comes back.","Reviewing at a glance how much of each language is done.","Loading a translation at runtime from StreamingAssets, via LocalizationFileLoader."],"walkthrough":[{"name":"Header row","what":"REQUIRED. A key column (named \"key\" by default, case-insensitive) plus one column per language."},{"name":"Language columns","what":"The header cell IS the locale code — en, fr, pt-BR. Whatever you write there becomes the LocaleAsset's Id. Blank headers are skipped, so a stray trailing comma is harmless."},{"name":"Key column","what":"One key per row. If no column is named \"key\", column 0 is used and a warning says so — a sheet headed \"ID\" still imports."},{"name":"Blank cell","what":"Not translated. Skipped, so the fallback language answers."},{"name":"Row starting with #","what":"A comment. Skipped entirely, so you can park a line without deleting it."},{"name":"Blank row","what":"Skipped. Spacer rows in a hand-edited sheet are fine."},{"name":"Short row","what":"Fine. Most spreadsheet exports drop trailing empty cells, and the missing ones read as untranslated."},{"name":"Duplicate key","what":"The first row wins, with a warning naming the key and the row number."},{"name":"Commas and quotes in text","what":"Handled — the parsing is CsvUtility, so a quoted field carrying commas, quotes or newlines survives intact."}],"usage":{"code":"// Read a sheet.\nLocalizationTable table = LocalizationCsv.Parse(File.ReadAllText(path));\n\nforeach (string code in table.LocaleCodes)\n    Debug.Log(code + \": \" + table.TranslatedCount(code) + \"/\" + table.Keys.Count);\n\n// Write one back out. alignColumns pads the columns into a readable table;\n// leave it off for a file going straight into Excel.\nstring readable = LocalizationCsv.ToCsv(table, \"key\", true);","codeNote":"Parse takes the file's text, not its path. LocalizationFileLoader is the component that actually reads a file at runtime, because StreamingAssets on Android cannot be opened with System.IO at all."},"apiNotes":{"Parse(string, string)":"Strips a leading byte-order mark before parsing. That matters more than it sounds: the exporter writes a BOM because Excel needs one to read UTF-8, and without stripping it the first header cell would come back as \"\\uFEFFkey\" and fail to match the key column.","ParseRows(IReadOnlyList<string[]>, string)":"The same logic against rows already parsed by CsvUtility. Use it when the text has been read for you, or to build a table from rows constructed in code.","BuildRows(LocalizationTable, string)":"The union of every key across every language, so a key only the newest language has still reaches the translator working on the others.","ToCsv(LocalizationTable, string, bool)":"The third argument aligns the columns. Read the gotcha below before turning it on for a file bound for Excel.","DefaultKeyColumnName":"\"key\". Pass something else to Parse if your sheet heads that column differently."},"gotchas":[{"title":"A translation cannot begin or end with a space","body":"Values are trimmed on import. They have to be: the padding that lines the columns up in an aligned file is leading whitespace on the next value, and it has to come back off. If edge whitespace genuinely matters for a string, use the JSON bundle format, which stores every character exactly as written."},{"title":"Aligned files show their padding in Excel","body":"Alignment is plain spaces after each comma, so the file stays valid CSV and re-imports identically. But Excel does not trim them, so an aligned file opened there shows leading spaces inside the cells. Export aligned for a file a person will READ; export unaligned for a file going to someone working in a spreadsheet."},{"title":"There is nowhere to put a display name","body":"A CSV has the locale code in the header and nothing else, so a language INTRODUCED by a CSV can only show its own code in a language picker. This is visible in the demo scene, where the runtime-loaded \"sv\" appears as \"sv\". The JSON bundle format carries display names and auto-detect languages; that is what it is for."},{"title":"This is NOT the shape CsvToScriptableObjectImporter reads","body":"That tool's columns are FIELDS of one asset per row. A translation sheet is transposed — columns are languages, rows are keys — so the two cannot read each other's files. What they share is CsvUtility, which is the part that actually matters."}],"seeAlso":["CsvUtility","LocalizationBundleJson","Localization","CsvToScriptableObjectImporter"],"src_uses":["CsvToScriptableObjectImporter","CsvUtility","LocalizationTable"],"src_usedBy":["LocalizationFileFormat","LocalizationFileLoader","LocalizationFileLocation","LocalizationImporterWindow","LocalizationLoadedEvent","LocalizationTable"],"src_extensionPoints":[],"parts":[{"id":"localization-table","name":"LocalizationTable","cat":"Data","src_typeKind":"class","src_ns":"Toolkit.Data.Localization","src_file":"Data/Localization/LocalizationCsv.cs","src_lines":[11,28],"src_base":null,"src_implements":[],"src_static":false,"src_internal":false,"src_runtime":true,"src_attributes":{},"src_typeComment":"A whole translation sheet in memory: the locale codes across the top, the keys down the side, and the text in between. Kept as a plain data holder so the CSV shape and the asset shape never have to know about each other — the importer, the exporter and the runtime file loader all meet here.","src_serialized":[],"src_members":[{"id":"List<string>()","sig":"public readonly List<string> LocaleCodes = new List<string>()","kind":"method","name":"List","static":false,"comment":null},{"id":"List<string>()","sig":"public readonly List<string> Keys = new List<string>()","kind":"method","name":"List","static":false,"comment":null},{"id":"ByLocale","sig":"public readonly Dictionary<string, Dictionary<string, string>> ByLocale = new Dictionary<string, Dictionary<string, string>>()","kind":"field","name":"ByLocale","static":false,"comment":null},{"id":"GetLocale(string)","sig":"public Dictionary<string, string> GetLocale(string localeCode)","kind":"method","name":"GetLocale","static":false,"comment":null},{"id":"TranslatedCount(string)","sig":"public int TranslatedCount(string localeCode)","kind":"method","name":"TranslatedCount","static":false,"comment":"How many of this sheet's keys the locale actually has text for — the number a translation-progress readout is asking for."}],"src_enumValues":[],"src_selfTest":null,"src_demoScene":[],"entryKind":"tool","status":"skeleton","summary":"A whole translation sheet in memory: the locale codes across the top, the keys down the side, and the text in between.","src_uses":["CsvToScriptableObjectImporter","CsvUtility","LocalizationCsv"],"src_usedBy":["LocaleBundle","LocaleBundleEntry","LocalizationBundleJson","LocalizationCsv","LocalizationFileFormat","LocalizationFileLoader","LocalizationFileLocation","LocalizationImporterWindow"],"src_extensionPoints":[],"foldedInto":"localization-csv"}]},{"id":"localization-bundle-json","name":"LocalizationBundleJson","cat":"Data","src_typeKind":"class","src_ns":"Toolkit.Data.Localization","src_file":"Data/Localization/LocalizationBundleJson.cs","src_lines":[71,157],"src_base":null,"src_implements":[],"src_static":true,"src_internal":false,"src_runtime":true,"src_attributes":{},"src_typeComment":"THE READABLE FORMAT. Every language in one indented JSON file, each with its code, its display name, the system language it serves, and its strings:  { \"locales\": [ { \"code\": \"fr\", \"displayName\": \"Français\", \"systemLanguage\": \"French\", \"strings\": { \"menu.start\": \"Démarrer\" } } ] }  Why this exists alongside CSV: a CSV is the right shape to HAND A TRANSLATOR (every language side by side in a spreadsheet) but a poor shape to read or edit by hand, and it has nowhere to put a display name or a system language — which is why a CSV-loaded language can only show its own code in a picker. This format has somewhere to put both, preserves leading and trailing spaces exactly (the CSV reader trims them), and diffs one line per string.  THIS IS THE ONE FILE IN THE FOLDER THAT NEEDS THE NEWTONSOFT PACKAGE (com.unity.nuget.newtonsoft-json). That is deliberate and it is why it is its own file: a flat string -> string map is served fine by the dependency-free LocalizationJson, and a project that does not want the package can delete this one script and lose nothing else. Newtonsoft is here because a nested object holding a Dictionary is exactly what Unity's own JsonUtility cannot deserialize.","src_serialized":[],"src_members":[{"id":"Parse(string)","sig":"public static LocaleBundle Parse(string json)","kind":"method","name":"Parse","static":true,"comment":null},{"id":"ToJson(LocaleBundle)","sig":"public static string ToJson(LocaleBundle bundle)","kind":"method","name":"ToJson","static":true,"comment":null},{"id":"ToTable(LocaleBundle)","sig":"public static LocalizationTable ToTable(LocaleBundle bundle)","kind":"method","name":"ToTable","static":true,"comment":"Converted to the same LocalizationTable a CSV produces, so importing a bundle and importing a sheet go down ONE code path rather than two that can drift apart."},{"id":"FromTable(LocalizationTable)","sig":"public static LocaleBundle FromTable(LocalizationTable table,","kind":"method","name":"FromTable","static":true,"comment":"The export direction. displayNames/systemLanguages are looked up per code and may be null — a bundle built from a plain CSV simply has nothing to put there."}],"src_enumValues":[],"src_selfTest":null,"src_demoScene":[],"entryKind":"tool","status":"published","summary":"The readable format: every language in one indented JSON file, display names and all.","overview":["THE FORMAT, in full — one object with a \"locales\" array, one entry per language:\n\n{\n  \"locales\": [\n    {\n      \"code\": \"fr\",\n      \"displayName\": \"Français\",\n      \"systemLanguage\": \"French\",\n      \"strings\": {\n        \"hud.greeting\": \"Bon retour, {0} !\",\n        \"menu.quit\": \"Quitter\",\n        \"menu.start\": \"Démarrer\"\n      }\n    }\n  ]\n}\n\nFour fields per language. `code` becomes the LocaleAsset's Id. `displayName` is what a language picker shows. `systemLanguage` is the NAME of a UnityEngine.SystemLanguage value — \"French\", \"ChineseSimplified\" — used to auto-pick this language on a matching device; leave it empty to opt out. `strings` is the key-to-text table.","Reach for this over CSV when a person is going to read or edit the file. It is the only format that can set a display name or an auto-detect language, it preserves leading and trailing spaces exactly where CSV trims them, and it diffs one line per string instead of one line per key across every language at once. CSV is still the right thing to hand a translator working in a spreadsheet."],"useCases":["Keeping translations in source control where every change diffs as one readable line.","Hand-editing a language without loading a spreadsheet.","Moving a set of languages between projects with their display names and auto-detect settings intact.","Shipping a runtime translation file where the language needs a proper name in the picker."],"usage":{"code":"// Read a bundle and turn it into the same table a CSV produces.\nLocaleBundle bundle = LocalizationBundleJson.Parse(File.ReadAllText(path));\nLocalizationTable table = LocalizationBundleJson.ToTable(bundle);\n\n// Write one out, carrying the two things a table cannot hold.\nLocaleBundle exported = LocalizationBundleJson.FromTable(table, displayNames, systemLanguages);\nFile.WriteAllText(path, LocalizationBundleJson.ToJson(exported));","codeNote":"Normally you never call any of this: Toolkit > Localization Importer imports and exports bundles through these methods, and LocalizationFileLoader reads one at runtime when its Format is set to Json Bundle."},"apiNotes":{"Parse(string)":"Returns an empty bundle rather than throwing if the file is malformed, and logs Newtonsoft's message — which names the line and position, the single most useful thing to print for a file a person edits by hand.","ToJson(LocaleBundle)":"Always indented, and always with keys sorted, so re-exporting unchanged data produces a byte-identical file and source control stays quiet.","ToTable(LocaleBundle)":"Flattens to the same LocalizationTable a CSV produces, which is why importing a bundle and importing a sheet go down one code path rather than two that can drift apart.","FromTable(LocalizationTable)":"The export direction. The displayNames and systemLanguages arguments are optional — a bundle built from a plain CSV simply has nothing to put in those fields."},"gotchas":[{"title":"This is the one file in the folder that needs the Newtonsoft package","body":"com.unity.nuget.newtonsoft-json, which this project already has. It is isolated in its own script deliberately: a flat string-to-string map is served fine by the dependency-free LocalizationJson, and a project that does not want the package can delete this single file and lose nothing else. Newtonsoft is here because a nested object holding a Dictionary is exactly what Unity's own JsonUtility cannot deserialize."},{"title":"A bundle import DOES overwrite display name and system language — a CSV import does not","body":"That asymmetry is deliberate, not an inconsistency. A bundle states both explicitly, so writing them is honouring the file. A CSV has nowhere to state them, so touching them would mean clobbering hand-set values with nothing. Font Override is never written by either."},{"title":"A bad systemLanguage costs one language its auto-detect, not the import","body":"The value is a SystemLanguage name and is parsed leniently: an unrecognised one logs a warning naming the locale and resolves to Unknown, which just means that language is never auto-selected. The strings still import."},{"title":"Key order in the file is not preserved","body":"Keys are always written sorted, whatever order they arrived in. That is what makes a re-export diff-free, and it groups \"menu.*\" together, but it does mean a hand-arranged file gets reordered the first time you export over it."}],"seeAlso":["LocalizationCsv","LocalizationJson","JsonHelper","Localization"],"src_uses":["LocaleAsset","LocaleBundle","LocaleBundleEntry","LocalizationJson","LocalizationTable"],"src_usedBy":["LocaleBundle","LocaleBundleEntry","LocalizationFileFormat","LocalizationFileLoader","LocalizationFileLocation","LocalizationImporterWindow","LocalizationLoadedEvent"],"src_extensionPoints":[],"parts":[{"id":"locale-bundle","name":"LocaleBundle","cat":"Data","src_typeKind":"class","src_ns":"Toolkit.Data.Localization","src_file":"Data/Localization/LocalizationBundleJson.cs","src_lines":[39,42],"src_base":null,"src_implements":[],"src_static":false,"src_internal":false,"src_runtime":true,"src_attributes":{},"src_typeComment":"","src_serialized":[],"src_members":[{"id":"List<LocaleBundleEntry>()","sig":"public List<LocaleBundleEntry> locales = new List<LocaleBundleEntry>()","kind":"method","name":"List","static":false,"comment":null}],"src_enumValues":[],"src_selfTest":null,"src_demoScene":[],"entryKind":"tool","status":"skeleton","summary":"","src_uses":["LocaleAsset","LocaleBundleEntry","LocalizationBundleJson","LocalizationJson","LocalizationTable"],"src_usedBy":["LocaleBundleEntry","LocalizationBundleJson","LocalizationFileFormat","LocalizationFileLoader","LocalizationFileLocation","LocalizationImporterWindow","LocalizationLoadedEvent"],"src_extensionPoints":[],"foldedInto":"localization-bundle-json"},{"id":"locale-bundle-entry","name":"LocaleBundleEntry","cat":"Data","src_typeKind":"class","src_ns":"Toolkit.Data.Localization","src_file":"Data/Localization/LocalizationBundleJson.cs","src_lines":[15,37],"src_base":null,"src_implements":[],"src_static":false,"src_internal":false,"src_runtime":true,"src_attributes":{},"src_typeComment":"One language inside a bundle file. These are plain data carriers for the JSON reader, NOT Unity serialized types — no [Serializable], no [SerializeField], nothing shows in an Inspector. The field names ARE the format, so they are deliberately plain and they are half the documentation: code            the locale code, \"en\" / \"fr\" / \"en-PT\". Becomes the LocaleAsset's Id. displayName     what a language picker shows, written in that language. systemLanguage  the NAME of a UnityEngine.SystemLanguage value, e.g. \"French\". Empty = no auto-detect. strings         the key -> text table.","src_serialized":[],"src_members":[{"id":"code","sig":"public string code = \"\"","kind":"field","name":"code","static":false,"comment":null},{"id":"displayName","sig":"public string displayName = \"\"","kind":"field","name":"displayName","static":false,"comment":null},{"id":"systemLanguage","sig":"public string systemLanguage = \"\"","kind":"field","name":"systemLanguage","static":false,"comment":null},{"id":"SortedDictionary<string, string>(StringComparer.Ordinal)","sig":"public SortedDictionary<string, string> strings = new SortedDictionary<string, string>(StringComparer.Ordinal)","kind":"method","name":"SortedDictionary","static":false,"comment":"SortedDictionary, not Dictionary: this decides the ORDER THE KEYS ARE WRITTEN IN, and a file that lives in source control and gets re-exported constantly needs that order to be stable or every export produces a meaningless whole-file diff. Sorting also groups \"menu.*\" together, which is how a person wants to read it anyway."},{"id":"ResolveSystemLanguage()","sig":"public SystemLanguage ResolveSystemLanguage()","kind":"method","name":"ResolveSystemLanguage","static":false,"comment":"Parsed leniently on purpose: this is a hand-editable file, and a typo in ONE language's systemLanguage should cost that one auto-detect, not the whole import."}],"src_enumValues":[],"src_selfTest":null,"src_demoScene":[],"entryKind":"tool","status":"skeleton","summary":"One language inside a bundle file.","src_uses":["LocaleAsset","LocaleBundle","LocalizationBundleJson","LocalizationJson","LocalizationTable"],"src_usedBy":["LocaleBundle","LocalizationBundleJson","LocalizationFileFormat","LocalizationFileLoader","LocalizationFileLocation","LocalizationImporterWindow","LocalizationLoadedEvent"],"src_extensionPoints":[],"foldedInto":"localization-bundle-json"}]},{"id":"localization-json","name":"LocalizationJson","cat":"Data","src_typeKind":"class","src_ns":"Toolkit.Data.Localization","src_file":"Data/Localization/LocalizationJson.cs","src_lines":[26,182],"src_base":null,"src_implements":[],"src_static":true,"src_internal":false,"src_runtime":true,"src_attributes":{},"src_typeComment":"Reads and writes the other shape translations arrive in: ONE FILE PER LANGUAGE, a flat object of key -> text.  { \"ui.start\": \"Start\", \"ui.quit\": \"Quit\" }  Nested objects are flattened with dots, so the equally common  { \"ui\": { \"start\": \"Start\", \"quit\": \"Quit\" } }  produces exactly the same keys — which is what makes a file exported from a web translation tool drop straight in.  WHY THIS EXISTS RATHER THAN JsonHelper: a localisation file is a string -> string map and nothing else, and JsonUtility cannot deserialize a Dictionary at all. The toolkit's JsonHelper can, but it needs the Newtonsoft package, and the convention here is that a tool does not drag a package in for one narrow job — the same reasoning that produced CsvUtility instead of a spreadsheet library. If your file has numbers, arrays or nested non-string values, it is not a localisation file: use JsonHelper for it.","src_serialized":[],"src_members":[{"id":"Parse(string)","sig":"public static Dictionary<string, string> Parse(string json)","kind":"method","name":"Parse","static":true,"comment":null},{"id":"ToJson(IReadOnlyDictionary<string, string>, bool)","sig":"public static string ToJson(IReadOnlyDictionary<string, string> strings, bool prettyPrint = true)","kind":"method","name":"ToJson","static":true,"comment":"Always written flat, one key per line, sorted — a localisation file lives in source control and gets re-exported constantly, so a stable line order is what keeps its diffs readable."}],"src_enumValues":[],"src_selfTest":null,"src_demoScene":[],"entryKind":"tool","status":"published","summary":"One flat { key: text } file holding ONE language. Zero dependencies, nested objects flattened with dots.","overview":["THE FORMAT, in full — a flat object of key to text, and nothing else:\n\n{\n  \"menu.start\": \"Start Game\",\n  \"menu.quit\": \"Quit\",\n  \"hud.greeting\": \"Welcome back, {0}!\"\n}\n\nOne file is ONE language; the importer asks you which locale code it belongs to, because the file does not say. Nested objects are flattened with dots, so the equally common\n\n{ \"menu\": { \"start\": \"Start Game\", \"quit\": \"Quit\" } }\n\nproduces exactly the same keys — which is what lets a file exported from a web translation tool drop straight in.","Use this when a file arrives in this shape from somewhere else. When you are choosing the shape yourself, the JSON bundle carries every language in one file along with their display names, and the CSV is what a translator wants."],"useCases":["Importing a per-language file produced by a web translation service.","Shipping a single extra language as a runtime patch file.","Keeping a project dependency-free while still using JSON."],"usage":{"code":"Dictionary<string, string> strings = LocalizationJson.Parse(File.ReadAllText(path));\nstring text = LocalizationJson.ToJson(strings);","codeNote":"Written flat and sorted, one key per line, whatever nesting it was read from — a localisation file lives in source control and gets re-exported constantly, so a stable line order is what keeps its diffs readable."},"apiNotes":{"Parse(string)":"Degrades rather than throwing. A malformed file stops at the break, KEEPS everything read before it, and logs the character position — a stray comma at the end of a 400-line file should not cost you the other 399 while you find it.","ToJson(IReadOnlyDictionary<string, string>, bool)":"Always flat, even for keys containing dots — it never re-nests. Non-ASCII is written through as-is rather than escaped, so a translator opening the file sees their own language and not a wall of \\u00e9."},"gotchas":[{"title":"Strings only — a number or an array stops the parse","body":"A localisation file is a string-to-string map and nothing else, so a non-string value is treated as an error, keeping what was read and logging where. If your file has numbers, arrays or booleans it is a data file rather than a localisation file: JsonHelper is the tool for that, and it has full Newtonsoft behind it."},{"title":"The file does not know which language it is","body":"There is no locale code in the format, so the importer and LocalizationFileLoader both ask you for one. Point them at the wrong file and the text lands in the wrong language with no complaint. The JSON bundle format does not have this problem — each entry names its own code."},{"title":"Dotted and nested keys collide silently","body":"Because nesting flattens with dots, { \"ui\": { \"start\": \"A\" } } and { \"ui.start\": \"B\" } are the same key. In one file the later one wins."}],"seeAlso":["LocalizationBundleJson","LocalizationCsv","JsonHelper","Localization"],"src_uses":["CsvUtility","JsonHelper"],"src_usedBy":["LocaleBundle","LocaleBundleEntry","LocalizationBundleJson","LocalizationFileFormat","LocalizationFileLoader","LocalizationFileLocation","LocalizationImporterWindow","LocalizationLoadedEvent"],"src_extensionPoints":[]}]},{"title":"Editor integration","entries":[{"id":"localization-importer-window","name":"LocalizationImporterWindow","cat":"Data","src_typeKind":"class","src_ns":"Toolkit.Data.EditorTools","src_file":"Data/Localization/Editor/LocalizationImporterWindow.cs","src_lines":[16,452],"src_base":"EditorWindow","src_implements":[],"src_static":false,"src_internal":false,"src_runtime":false,"src_attributes":{"menuItem":["Toolkit/Localization Importer"]},"src_typeComment":"Toolkit > Localization Importer: turns a translator's spreadsheet into LocaleAssets plus the LocaleRegistry that lists them, and exports the round trip back out so new keys reach the translator.  Re-importing UPDATES the existing assets in place rather than replacing them, so their GUIDs survive and every scene reference to the registry keeps working — the whole point of doing this through the AssetDatabase instead of writing .asset files directly.","src_serialized":[],"src_members":[{"id":"ShowWindow()","sig":"public static void ShowWindow() => GetWindow<LocalizationImporterWindow>(\"Localization Importer\")","kind":"method","name":"ShowWindow","static":true,"comment":null},{"id":"Import(LocalizationTable, string, string, LocaleBundle)","sig":"public static string Import(LocalizationTable table, string outputFolder, string registryName, LocaleBundle metadata = null)","kind":"method","name":"Import","static":true,"comment":"Public and static so the self-test can drive the whole import without a window open.  `metadata` is supplied only by a JSON bundle import. It is the reason a bundle CAN set a language's display name and system language while a CSV cannot: the bundle states them explicitly, so writing them is honouring the file, whereas a CSV import that touched them would be silently clobbering hand-set values with nothing."},{"id":"GenerateKeyAssets(LocaleRegistry, string)","sig":"public static string GenerateKeyAssets(LocaleRegistry registry, string folder)","kind":"method","name":"GenerateKeyAssets","static":true,"comment":"Public and static for the same reason Import is: the self-test drives it with no window open.  Matched by PATH, not by scanning for a matching key, so re-running updates the same assets and every LocalizedText already pointing at one keeps working. That is the whole value of a key asset, and it would be undone by a generator that deleted and recreated."},{"id":"BuildTableFromRegistry(LocaleRegistry)","sig":"public static LocalizationTable BuildTableFromRegistry(LocaleRegistry registry)","kind":"method","name":"BuildTableFromRegistry","static":true,"comment":"The union of every key in every locale, sorted — a key that only the newest language has still needs to reach the translator working on the others. Sorted rather than encounter-ordered so two exports of the same data produce byte-identical files and source control stays quiet."},{"id":"EnsureFolder(string)","sig":"public static void EnsureFolder(string folder)","kind":"method","name":"EnsureFolder","static":true,"comment":"AssetDatabase.CreateFolder only makes ONE level at a time, so \"Assets/A/B/C\" has to be walked."}],"src_enumValues":[],"src_selfTest":null,"src_demoScene":[],"entryKind":"editor","status":"published","summary":"Turns a sheet or a bundle into LocaleAssets plus the registry that lists them — and exports the round trip back.","overview":["The one-off step between a translation file and a working game. Point it at a CSV, a flat JSON file or a JSON bundle, press Import, and it creates or updates one LocaleAsset per language plus the LocaleRegistry that lists them. Export writes the round trip back out: every key that exists, translations filled in, the rest blank — the sheet you hand a translator so they can see exactly what is left.","Re-importing UPDATES the existing assets in place rather than replacing them, so their GUIDs survive and every scene reference to the registry keeps working. That is the whole reason this goes through the AssetDatabase instead of writing .asset files directly."],"useCases":["Setting a project up: one sheet in, a working registry out.","Taking a returned translation and re-importing it without touching a scene.","Sending a translator a fresh sheet containing the keys added since last time.","Converting between the CSV and JSON bundle formats — import one, export the other."],"whereToFind":"Toolkit ▸ Localization Importer","walkthrough":[{"group":"Import","name":"Source Format","what":"Csv (a sheet, a column per language), Json (one flat file, ONE language) or Json Bundle (every language in one readable file)."},{"group":"Import","name":"Source File","what":"The file to read. Browse filters to .csv or .json to match the format."},{"group":"Import","name":"Key Column Name","what":"Csv only. Which header cell holds the keys; defaults to \"key\". If no column matches, column 0 is used and a warning says so."},{"group":"Import","name":"Locale Code","what":"Json only. Which language the file's text belongs to, since a flat JSON file does not say. Json Bundle does not ask — each entry names its own."},{"group":"Import","name":"Output Folder","what":"Where the assets are written. Must be inside Assets. Created if missing, nested levels included."},{"group":"Import","name":"Registry Asset Name","what":"File name for the LocaleRegistry, created alongside the locales. Point a re-import at the same name to keep the same asset."},{"group":"Import","name":"Import","what":"Runs it. Disabled until the file exists and the output folder is inside the project. The result lists each language and how much of it is translated."},{"group":"Export","name":"Registry","what":"The LocaleRegistry to export. Every language it lists, and the union of every key across them."},{"group":"Export","name":"Align CSV Columns","what":"Pads the exported CSV into a readable table. Still valid CSV, and the padding is trimmed back off on import. Turn it OFF for a file going straight into Excel, which shows the padding as leading spaces."},{"group":"Export","name":"Export CSV...","what":"The format to send someone working in a spreadsheet. Written with a BOM, which is what Excel needs to read UTF-8."},{"group":"Export","name":"Export JSON Bundle...","what":"The format to read or edit yourself. Also carries each language's display name and auto-detect language, which a CSV has nowhere to put."},{"group":"Export","name":"Last Result","what":"What the previous import or export did, per language — kept on screen rather than only in the console."}],"apiNotes":{"Import(LocalizationTable, string, string, LocaleBundle)":"Public and static so it can run without a window open — which is exactly what the demo scene builder does, producing the demo's locale assets through the real importer so a broken import path stops the build rather than leaving a stale asset. The LocaleBundle argument is the metadata a bundle carries and a CSV cannot; pass null for a CSV.","BuildTableFromRegistry(LocaleRegistry)":"The union of every key across every language, sorted — so a key only the newest language has still reaches the translator working on the others, and two exports of unchanged data produce identical files.","EnsureFolder(string)":"Walks a nested path creating each level, because AssetDatabase.CreateFolder only makes one at a time."},"gotchas":[{"title":"A CSV import never touches Display Name, System Language or Font Override","body":"They are authored once per language, and a re-import happens every time a translator sends a new sheet — overwriting them would lose hand-set values on every round trip. A JSON BUNDLE import does write the first two, because the file states them explicitly. Font Override is never written by any import."},{"title":"Re-import into the same folder and registry name, or you get a second set","body":"The assets are matched by path — Locale_<code>.asset in the output folder. Import the same sheet into a different folder and you get a parallel set of assets and a second registry, with the scene still pointing at the first."},{"title":"Import does not add the registry to a scene","body":"It creates the assets and the registry. Assigning that registry to a LocalizationManager is still a manual step — and until you do it, every key in the game renders as a missing-key marker."}],"seeAlso":["Localization","LocalizationCsv","LocalizationBundleJson","LocaleRegistry"],"src_uses":["LocaleAsset","LocaleBundle","LocaleBundleEntry","LocaleRegistry","LocalizationBundleJson","LocalizationCsv","LocalizationJson","LocalizationTable"],"src_usedBy":[],"src_extensionPoints":[]},{"id":"localization-editor-window","name":"LocalizationEditorWindow","cat":"Data","src_typeKind":"class","src_ns":"Toolkit.Data.EditorTools","src_file":"Data/Localization/Editor/LocalizationEditorWindow.cs","src_lines":[18,319],"src_base":"EditorWindow","src_implements":[],"src_static":false,"src_internal":false,"src_runtime":false,"src_attributes":{"menuItem":["Toolkit/Localization Editor"]},"src_typeComment":"Toolkit > Localization Editor: every language side by side, editable in place.  The importer round trip is right for a translator and wrong for you fixing one word. This edits the LocaleAssets directly — no file, no export, no re-import — and does the two things a spreadsheet cannot: RENAMING A KEY updates every language AND every LocalizedStringAsset pointing at it in one action, and an untranslated cell is visibly blank next to the language that does have it.  Reads the assets' RAW entry lists rather than their runtime lookups, deliberately: the lookup drops empty text (that is what makes the fallback work), and an empty cell is precisely what this window exists to show you.","src_serialized":[],"src_members":[{"id":"ShowWindow()","sig":"public static void ShowWindow() => GetWindow<LocalizationEditorWindow>(\"Localization Editor\")","kind":"method","name":"ShowWindow","static":true,"comment":null}],"src_enumValues":[],"src_selfTest":null,"src_demoScene":[],"entryKind":"editor","status":"published","summary":"Every language side by side, editable in place. Renaming a key updates all of them at once.","overview":["The importer round trip is right for a translator and wrong for you fixing one word. This edits the LocaleAssets directly — no file, no export, no re-import — with one row per key and one column per language, and an untranslated cell visibly blank beside the language that does have it.","It also does the thing a spreadsheet cannot do safely: RENAMING A KEY updates every language AND every LocalizedStringAsset pointing at it, in one action. Rename a key in a sheet and every scene that typed the old one breaks silently."],"useCases":["Fixing a word without opening a spreadsheet or re-importing.","Adding a key and filling it in across every language in one pass.","Renaming a key safely once it is already used.","Checking how much of a language is done — each column header carries its own count.","Finding a line you half remember: the filter searches the TEXT as well as the keys."],"whereToFind":"Toolkit ▸ Localization Editor","walkthrough":[{"name":"Registry","what":"The LocaleRegistry to edit. Its locales become the columns."},{"name":"Filter","what":"Matches keys AND translated text, case-insensitively — so you can find a line by something you remember of its wording."},{"name":"Reload","what":"Re-reads the assets. Use it after an import, or if something edited them outside this window."},{"name":"Save Assets","what":"Flushes to disk. Edits apply to the assets immediately and mark them dirty; this is what makes Unity write them out now rather than at some later moment."},{"name":"New Key / Add","what":"Adds a row. Disabled for a key that already exists. The key exists only in this window until you type text for it in at least one language."},{"name":"Key cell","what":"Renames on Enter or focus loss, across every language and every Localized String asset. Refuses to rename onto an existing key rather than merging two keys and discarding one language's text."},{"name":"Text cell","what":"Commits on Enter or focus loss. Clearing a cell REMOVES that entry, which is what makes the fallback language answer for it again."},{"name":"×","what":"Removes the key from every language. Asks first, and says how many Localized String assets still point at it."}],"gotchas":[{"title":"A LocalizedText that TYPED the key is not updated by a rename","body":"The rename reaches every locale asset and every LocalizedStringAsset, because both are assets it can find. A typed key lives inside a scene or prefab and there is no reference to follow. That asymmetry is the strongest practical argument for key assets on anything you might rename — and the rename's own console message says so."},{"title":"Clearing a cell deletes the entry rather than storing an empty one","body":"That is deliberate: it keeps the assets the same shape the importer writes, and an empty entry and a missing entry mean the same thing at runtime anyway. The row does not disappear while you are working — the window remembers the key for the session — but a key left empty in every language is gone after a Reload, because a key with no text in any language does not exist."},{"title":"Edits are immediate, not staged","body":"There is no Apply or Revert. Each committed cell writes to its asset through SerializedObject straight away, so Ctrl+Z works exactly as it does in the Inspector, and Save Assets only controls when the file is written."},{"title":"It draws every visible row each repaint","body":"Fine for a few hundred keys, which is where the table shape is most useful anyway. For a very large project, filter first — or do bulk work in a spreadsheet, which is what the CSV export is for."}],"seeAlso":["Localization","LocalizationImporterWindow","LocalizedStringAsset","LocaleAsset"],"src_uses":["LocaleAsset","LocaleEntry","LocaleRegistry","LocalizedStringAsset","LocalizedText"],"src_usedBy":[],"src_extensionPoints":[]},{"id":"localization-scene-setup","name":"LocalizationSceneSetup","cat":"Data","src_typeKind":"class","src_ns":"Toolkit.Data.EditorTools","src_file":"Data/Localization/Editor/LocalizationSceneSetup.cs","src_lines":[18,98],"src_base":null,"src_implements":[],"src_static":true,"src_internal":false,"src_runtime":false,"src_attributes":{"menuItem":["Toolkit/Localization/Set Up In This Scene"]},"src_typeComment":"Toolkit > Localization > Set Up In This Scene.  The four steps between \"I imported a sheet\" and \"a label shows French\" are: make a GameObject, add a LocalizationManager, find the registry, assign it. None of them is a decision — which is exactly the kind of thing a menu item should do for you. Same reasoning and shape as PlayerCameraRigSetup: not a prefab, because a prefab could not find YOUR registry, and the component is already plug-and-play on its own, so this is convenience rather than a requirement.  Safe to run twice: an existing manager is configured and selected rather than duplicated — which also makes it a usable \"did I wire this up?\" check on a scene someone else built.","src_serialized":[],"src_members":[],"src_enumValues":[],"src_selfTest":null,"src_demoScene":[],"entryKind":"editor","status":"published","summary":"One menu item that creates the manager, finds the registry and wires them together.","overview":["The steps between \"I imported a sheet\" and \"a label shows French\" are: make a GameObject, add a LocalizationManager, find the registry, assign it, pick a default and fallback language. None of them is a decision — which is exactly the kind of thing a menu item should do for you.","Offered instead of a prefab for the same reason as the camera rig's one-click setup: a prefab could not find YOUR registry. The component is already plug-and-play on its own, so this is convenience rather than a requirement."],"useCases":["Setting up localisation in a new scene without looking anything up.","Checking whether a scene someone else built is actually wired — it is safe to run on a scene that already has a manager.","Getting sensible default and fallback locale codes instead of typing \"en\" into a project that is not in English."],"whereToFind":"Toolkit ▸ Localization ▸ Set Up In This Scene","walkthrough":[{"name":"Existing manager","what":"Configured and selected rather than duplicated, so running it twice is harmless."},{"name":"Registry","what":"Assigned automatically when the project contains exactly ONE LocaleRegistry. With several it says so and leaves the choice to you; with none it tells you to import a sheet first."},{"name":"Default / Fallback Locale Code","what":"Both set to the FIRST locale in the registry, which is nearly always the language the game was written in — and always a better guess than a hardcoded \"en\"."},{"name":"Result","what":"Logged in full: what it created, what it assigned, and what to do next."}],"gotchas":[{"title":"It deliberately does NOT create a registry when none exists","body":"An empty registry would let the scene look wired while every key rendered as a missing-key marker — worse than an obviously missing reference. Import a sheet first with the Localization Importer."},{"title":"It only handles the scene-level wiring","body":"Labels still need a LocalizedText each. That part is genuinely per-label work and nothing can guess which of your labels are meant to be translated."},{"title":"It will not choose between several registries","body":"A project with more than one LocaleRegistry gets a report and no assignment, rather than a coin toss that silently ships the wrong set of languages."}],"seeAlso":["Localization","LocalizationImporterWindow","PlayerCameraRigSetup"],"src_uses":["LocaleAsset","LocaleRegistry","LocalizationManager","LocalizedText","PlayerCameraRigSetup"],"src_usedBy":[],"src_extensionPoints":[]},{"id":"localized-text-editor","name":"LocalizedTextEditor","cat":"Data","src_typeKind":"class","src_ns":"Toolkit.Data.EditorTools","src_file":"Data/Localization/Editor/LocalizedTextEditor.cs","src_lines":[18,151],"src_base":"Editor","src_implements":[],"src_static":false,"src_internal":false,"src_runtime":false,"src_attributes":{},"src_typeComment":"A localisation key is an opaque string, so the one thing this inspector has to answer is \"did I spell it right, and what does it actually say?\" — without entering Play mode. It shows the key's text in every language the project has, and offers a picker of the keys that really exist, which is the difference between a typo caught now and a #ui.strat_button# in a screenshot later.  It also makes the component's one piece of hidden behaviour visible: when a Localized String ASSET is assigned it wins, and the typed Key field is inert. A greyed-out field that says why beats a field that silently does nothing.","src_serialized":[],"src_members":[{"id":"OnInspectorGUI()","sig":"public override void OnInspectorGUI()","kind":"method","name":"OnInspectorGUI","static":false,"comment":null}],"src_enumValues":[],"src_selfTest":null,"src_demoScene":[],"entryKind":"editor","status":"published","summary":"The LocalizedText inspector: previews the key in every language and offers a picker of real keys.","overview":["A localisation key is an opaque string, so the one question this inspector has to answer is \"did I spell it right, and what does it actually say?\" — without entering Play mode. Under the normal fields it lists the key's text in every language the project has, warns when a key resolves nowhere, and offers a Pick Key button listing the keys that genuinely exist."],"useCases":["Catching a typo now instead of finding #ui.strat_button# in a screenshot later.","Checking which languages have translated a line, while laying the screen out.","Finding the right key without opening the sheet."],"walkthrough":[{"name":"Preview","what":"One row per language: the text, or \"— not translated —\". Warns if the key is in no locale at all."},{"name":"Pick Key...","what":"A menu of every key that exists across the registry, with the current one ticked."}],"gotchas":[{"title":"It previews the registry the SCENE points at, not an arbitrary one","body":"It looks for a LocalizationManager in the open scene first, because that is the registry the label will actually read from at runtime. Only if there is none — a prefab, or a scene not set up yet — does it fall back to the first LocaleRegistry in the project, which may not be the one that ships."},{"title":"No preview means no registry, not a broken key","body":"With no LocaleRegistry anywhere it says so and stops, rather than reporting every key as missing."}],"seeAlso":["LocalizedText","Localization"],"src_uses":["LocaleAsset","LocaleEntry","LocaleRegistry","LocalizationManager","LocalizedStringAsset","LocalizedText"],"src_usedBy":[],"src_extensionPoints":[]}]}],"overview":["Your UI stops holding text and starts holding KEYS. A label says \"menu.start\", and what the player reads comes from whichever language is active — so adding a language is a spreadsheet column, not a pass over every scene. It is a lookup table you or a translator fill in ahead of time, not machine translation: nothing is generated at runtime.","Built on the pieces that were already here — a language is a GameDataAsset and the list of them is a GameDataRegistry, so looking one up by code is the registry's existing GetById; the sheet is read by CsvUtility, so a comma inside a translated sentence survives.","Start with the setup steps below. Each script's own settings are documented on its section further down — LocaleAsset for what a language asset needs, LocalizedText for what goes on a label, and LocalizationCsv / LocalizationBundleJson / LocalizationJson for the exact shape of each file format."],"features":[{"name":"Locale assets","what":"one asset per language, holding its key-to-text table, display name and an optional font."},{"name":"LocalizedText","what":"drop it next to any TMP_Text or UI.Text, type a key, and it rewrites itself whenever the language changes."},{"name":"Draggable key assets","what":"optional LocalizedStringAssets you drag onto a label instead of typing a key, so a typo is impossible and a rename reaches every user."},{"name":"Fallback chain","what":"a key missing from the current language is answered by the fallback language instead of rendering blank."},{"name":"Format arguments","what":"\"You have {0} coins\" takes its values once and keeps them across every language switch."},{"name":"Three file formats","what":"a CSV sheet for translators, a readable JSON bundle for humans and source control, and flat per-language JSON for files that arrive that way."},{"name":"Import and export","what":"one click each way, so new keys reach a translator and returned work reaches the game without editing a scene."},{"name":"Runtime loading","what":"an optional loader reads a file at Play time and layers it over the shipped languages, or adds one that has no asset at all."},{"name":"Localization Editor","what":"every language side by side, editable in place, with a rename that updates all of them and the key assets at once."},{"name":"One-click scene setup","what":"a menu item that creates the manager, finds the registry and picks sensible default and fallback languages."}],"useCases":["Shipping a game in more than one language without duplicating a scene per language.","Handing a translator a spreadsheet, getting it back, and re-importing it without touching any scene.","Patching a typo in a shipped language, or accepting a community translation, without a rebuild.","Seeing at a glance which lines a half-finished language still owes you."],"params":[{"field":"registry","why":"The list of every language the game ships with.","tuning":"The one field that must be set. Left empty, the manager warns once and every key renders as a missing-key marker — which is loud on purpose, because a silently English build is the failure that ships."},{"field":"defaultLocaleCode","why":"The language used when there is no saved choice and no system-language match.","tuning":"Normally the language the game was written in. If the code names no locale in the registry, the first locale is used instead and the console says so."},{"field":"fallbackLocaleCode","why":"The language consulted when the current one has no text for a key.","tuning":"This is what makes a half-translated language shippable. Leave it empty only if you would rather see the missing-key marker than the original wording."},{"field":"matchSystemLanguageOnFirstRun","why":"On a first launch, pick the language matching the device.","tuning":"Only matches locales whose Target System Language is set — the code is never guessed, so a non-standard code like \"en-PT\" can never be picked by accident. Turn it off for a demo or a test that must start the same way every time."},{"field":"rememberSelection","why":"Persist the chosen language across restarts.","tuning":"Writes one PlayerPrefs string rather than a save file. Worth turning off in a scene you are testing, or your own machine keeps answering with yesterday's click."},{"field":"playerPrefsKey","why":"The PlayerPrefs key used to remember the choice.","tuning":"Change it only if it collides with something; changing it later resets every existing player's language to the default."},{"field":"missingKeyDisplay","why":"What a key with no text anywhere renders as.","tuning":"MarkedKey (#ui.start#) is the default because it is impossible to miss in a screenshot. Key is quieter for a shipped build; Empty hides the problem and should be a deliberate choice."},{"field":"logMissingKeys","why":"Warn the first time each missing key is asked for.","tuning":"Once per key, not once per frame — a label refreshing every frame would otherwise bury the console. The set is cleared on a language change, so a gap in the NEW language still gets reported."}],"usage":{"code":"// Most labels need no code at all: add a LocalizedText beside the TMP_Text and type the key.\n\n// Reading a string from anywhere, holding no reference:\nstring title = LocalizationManager.Instance.Get(\"demo.title\");\nstring coins = LocalizationManager.Instance.Get(\"hud.score\", 7, 10);   // fills {0} and {1}\n\n// A language picker button:\nLocalizationManager.Instance.SetLocale(\"fr\");\n\n// Arguments for a label are set ONCE and survive every later language change:\nLocalizedText greeting = greetingLabel.GetComponent<LocalizedText>();\ngreeting.SetArguments(playerName);","codeNote":"Building the assets is a separate, one-off step: Toolkit > Localization Importer, point it at a CSV whose header is key,en,fr,de and press Import."},"apiNotes":{"Get(string)":"The whole point of the tool. Current locale, then the fallback locale, then the missing-key display — it never throws and never returns null, so a label always has something to render.","Get(string, params object[])":"Same lookup, then string.Format. A broken format string in a translation returns the raw template and names the key in the console rather than throwing FormatException in a language nobody on the team reads.","SetLocale(string)":"Returns false for a code that names no locale, leaving the current language untouched. Re-selecting the language already active is a no-op and does NOT fire OnLocaleChanged, so a picker can call it freely.","IsTranslated(string)":"Asks about the CURRENT locale only. This is the one that distinguishes a real translation from a fallback hit — HasKey cannot, because it counts the fallback as an answer.","HasKey(string)":"True if anything will render for this key, in the current locale or the fallback. Use it to spot a key that is genuinely absent everywhere.","AvailableLocaleCodes":"The codes a language picker should offer, in registry order, with any locale added at runtime appended. Reading it initialises the manager, so it is safe as the first call.","AddOrOverrideLocale(string, string, IDictionary<string, string>)":"Merges text into a language or creates one that has no asset at all. Keys not mentioned are left alone, so a patch file only carries the lines it changes — and the LocaleAsset on disk is never modified.","Rebuild()":"Re-reads the registry. It DISCARDS everything AddOrOverrideLocale added, so re-apply your runtime files after calling it.","CurrentFont":"The active locale's Font Override, or null. LocalizedText applies it for you; you only need this to font-swap something that is not a LocalizedText."},"gotchas":[{"title":"A blank cell means UNTRANSLATED, not empty string","body":"An empty cell in the sheet, and an entry with empty text in a locale asset, are both skipped entirely rather than stored — so the fallback language answers instead of the player reading a blank label. A half-filled sheet is the normal state of a translation project, so this is the behaviour that matters most. If you genuinely want a line to render as nothing, give that key a space, not an empty cell."},{"title":"The default font cannot draw most of the world's languages","body":"Unity's LiberationSans SDF ships as a STATIC atlas of about 250 characters — Latin-1 and some punctuation. French, German, Spanish and the Nordic languages are fine; Chinese, Japanese, Korean, Arabic, Hebrew, Thai and Cyrillic render as empty boxes. That is a font problem, not a localisation one: give that LocaleAsset a Font Override built with the right character set and LocalizedText swaps to it automatically."},{"title":"Re-importing updates in place, and never touches the three hand-set fields","body":"A second import writes to the same assets, so their GUIDs survive and every scene reference keeps working. Display Name, Target System Language and Font Override are deliberately left alone — they are authored once per language, not re-sent with every sheet a translator returns."},{"title":"Three formats, and which one to reach for","body":"CSV is what you hand a translator: every language side by side in a spreadsheet, unfinished cells visibly blank. JSON BUNDLE is what you read and edit yourself: one indented file, every language, and the only format that can also carry a display name and an auto-detect language. Flat JSON is for files that arrive in that shape from a web translation tool. They all import to the same assets, and the importer converts between them — import one, export another."},{"title":"CSV trims leading and trailing spaces; the JSON bundle does not","body":"The exporter can pad a CSV's columns into a readable table, and that padding is leading whitespace on the next value, so values are trimmed on import. The consequence is real: a translation cannot begin or end with a space in a CSV. If one genuinely needs to, keep that language in a JSON bundle, which stores every character exactly as written."},{"title":"Runtime loading is a coroutine, so its text lands a frame or two late","body":"LocalizationFileLoader reads through UnityWebRequest rather than File.ReadAllText, because on Android StreamingAssets lives inside the compressed APK where System.IO cannot open it at all. The cost is that the file arrives after Start. Labels do not need handling for this — the merge fires OnLocaleChanged and every LocalizedText re-reads itself — but code that samples a string in Start may see the pre-patch text."},{"title":"LocalizedText writes to a text component on its OWN GameObject","body":"Leave the target fields empty and it looks for a TMP_Text, then a UI.Text, on the same object — not in children. On a Button, the component belongs on the Label child, not on the Button."},{"title":"LocalizationJson reads strings only","body":"A flat (or nested, dot-flattened) object of text. A number, array or boolean value stops the parse at that point, keeps everything read before it, and logs where. That is the whole format a localisation file needs; anything richer is a data file, and JsonHelper is the tool for it."},{"title":"The importer cannot read a CsvToScriptableObject-style sheet, and vice versa","body":"That tool's columns are FIELDS of one asset per row. A translation sheet is transposed — columns are languages, rows are keys — which is why this has its own importer window. The two are not interchangeable, and the parsing itself is shared through CsvUtility."},{"title":"A rename reaches key ASSETS, not typed keys","body":"The Localization Editor's rename updates every locale and every LocalizedStringAsset, because both are assets it can find. A key TYPED into a LocalizedText lives inside a scene or prefab with no reference to follow, so it is left behind. That is the practical argument for using a key asset on anything you might rename — and it is why the two styles are allowed to coexist rather than one replacing the other."}],"seeAlso":["CsvUtility","GameData","CsvToScriptableObjectImporter","Singleton<T>","JsonHelper"],"walkthrough":[{"step":"Write a translation file. The quickest start is a CSV: a header row reading key,en,fr then one row per line of text. The exact shape of all three formats is documented on the File formats sections below.","whatYouSee":"a file with one column per language"},{"step":"Open Toolkit > Localization Importer, pick the Source Format, Browse to your file, set Output Folder (anywhere under Assets) and press Import.","whatYouSee":"one Locale_<code>.asset per language plus a LocaleRegistry, and a report of how much of each language is translated"},{"step":"Open each new LocaleAsset and fill in Display Name (what a language picker shows) and, if you want first-launch auto-detection, Target System Language. A JSON bundle import fills both for you; a CSV import cannot, because a CSV has nowhere to state them.","whatYouSee":"\"Français\" instead of \"fr\" in a picker"},{"step":"Wire the scene: Toolkit > Localization > Set Up In This Scene creates the LocalizationManager, assigns the registry if the project has exactly one, and sets Default and Fallback Locale Code to its first language. Doing it by hand is fine too — it is one component and one reference.","whatYouSee":"a selected LocalizationManager and a console line saying exactly what it wired"},{"step":"On each label, add a LocalizedText component and type its key. The inspector previews the text in every language and has a Pick Key button listing the keys that really exist.","whatYouSee":"the preview showing the line in each language, or a warning that the key resolves nowhere"},{"step":"OPTIONAL, for keys you would hate to mistype: press Generate Key Assets in the importer, then DRAG the resulting Localized String asset onto a label's Key Asset field instead of typing the key. The two styles mix freely — the asset just wins where both are set.","whatYouSee":"the typed Key field greying out, with the asset's key shown under it"},{"step":"For a line with a value in it — \"You have {0} coins\" — call SetArguments once from your own code. The values are remembered and re-applied on every later language change.","whatYouSee":"the number surviving a language switch without any further calls"},{"step":"Switch language from a button with LocalizationManager.Instance.SetLocale(\"fr\"). Every LocalizedText in the scene updates itself.","whatYouSee":"the whole UI re-reading at once"},{"step":"When keys have been added, press Export CSV in the importer and send that sheet out. It contains every key, with what exists filled in and the rest blank.","whatYouSee":"exactly what the translator still owes you"},{"step":"To fix wording later, use Toolkit > Localization Editor rather than the sheet: every language side by side, and renaming a key there updates all of them and every key asset in one action.","whatYouSee":"a rename that does not break the scenes already using the key"}]}],"groups":[]};
